insert into questions (id, category, question, option_a, option_b, option_c, correct, explanation, image_url, exam) values
(1, 'Geschiedenis en Geografie', 'Hoe werd Nederland in de 17e eeuw rijk?', 'door oorlog', 'door handel', 'door kunst', 'B', 'In de 17e eeuw (de Gouden Eeuw) werd Nederland rijk dankzij internationale handel, voornamelijk via de VOC (Vereenigde Oost-Indische Compagnie).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/3/256984/Shutterstock_152105888_v.png', null),
(2, 'Geschiedenis en Geografie', 'Wat kun je nu nog in Nederland zien uit de 17e eeuw?', 'molens', 'grachtenpanden', 'polders', 'B', 'De Amsterdamse grachtenpanden werden gebouwd in de 17e eeuw en staan op de UNESCO-werelderfgoedlijst.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/4/256985/VOC_v.png', 1),
(3, 'Geschiedenis en Geografie', 'Hoeveel provincies heeft Nederland?', '10', '12', '15', 'B', 'Nederland is verdeeld in 12 provincies, van Groningen in het noorden tot Zeeland in het zuidwesten.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/5/256986/Shutterstock_2173241453_bewerkt_v.png', null),
(4, 'Geschiedenis en Geografie', 'In welke provincie ligt de hoofdstad van Nederland?', 'in Noord-Holland', 'in Flevoland', 'in Zuid-Holland', 'A', 'Amsterdam is de hoofdstad van Nederland en ligt in de provincie Noord-Holland. Den Haag is de regeringsstad.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/6/256987/Shutterstock_2494477129_v.png', null),
(5, 'Geschiedenis en Geografie', 'Mahmoud wil met de trein reizen. Wat heeft hij nodig?', 'een OV-chipkaart of een pinpas', 'een formulier', 'een recept', 'A', 'In het Nederlandse openbaar vervoer betaal je met een OV-chipkaart of een contactloze betaalpas. Een formulier of recept is niet nodig.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/7/256988/Shutterstock_179001425_v.png', null),
(6, 'Geschiedenis en Geografie', 'Wat is het Wilhelmus?', 'De Nederlandse grondwet', 'Het Nederlandse voetbalteam', 'Het Nederlandse volkslied', 'C', 'Het Wilhelmus is het Nederlandse volkslied. Het is een van de oudste volksliederen ter wereld en dateert uit de 16e eeuw.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/8/256989/Shutterstock_322053863_v.png', null),
(7, 'Geschiedenis en Geografie', 'Waarom is Den Haag een belangrijke stad?', 'De regering van Nederland werkt in Den Haag.', 'Den Haag is de hoofdstad van Nederland.', 'De meeste Nederlandse handel is in Den Haag.', 'A', 'Den Haag is de regeringsstad van Nederland: het parlement, de ministeries en de Tweede Kamer zijn er gevestigd. Amsterdam is de hoofdstad.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/9/256990/Shutterstock_634484750_bewerkt_v.png', null),
(8, 'Geschiedenis en Geografie', 'Na de Tweede Wereldoorlog kwamen er veel arbeidsmigranten naar Nederland. Wat zijn dat?', 'mensen uit andere landen die Nederland bevrijdden', 'mensen uit andere landen die familie in Nederland hebben', 'mensen uit andere landen die in Nederland komen werken', 'C', 'Gastarbeiders (arbeidsmigranten) zijn mensen die vanuit andere landen naar Nederland kwamen om hier te werken, met name in de jaren ''60 en ''70 van de 20e eeuw.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/10/256991/Shutterstock_249572968_v.png', null),
(9, 'Geschiedenis en Geografie', 'Nederland is lid van de EU. Wat is de EU?', 'een organisatie van landen in Europa die wetten maakt', 'een organisatie van landen in Europa en Noord-Amerika die zorgt voor vrede en veiligheid', 'een organisatie van landen over de hele wereld die samenwerken en afspraken maken', 'A', 'De EU (Europese Unie) is een organisatie van Europese landen die samenwerken op het gebied van wetgeving, handel en beleid.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/11/256992/EU_v.png', null),
(10, 'Geschiedenis en Geografie', 'Nederland is lid van de NAVO. Wat is het doel van de NAVO?', 'zorgen voor betere handel', 'zorgen voor vrede en veiligheid', 'zorgen voor arbeidsmigranten', 'B', 'De NAVO (Noord-Atlantische Verdragsorganisatie) is een militair bondgenootschap dat vrede en veiligheid waarborgt voor de lidstaten.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/12/256993/Shutterstock_349871213_v.jpg', 1),
(11, 'Geschiedenis en Geografie', 'Sama heeft een Nederlands paspoort. Ze wil in Frankrijk studeren. Kan dat?', 'Ja, dat kan.', 'Nee, dat kan niet.', 'Nee, maar ze kan wel in Frankrijk werken.', 'A', 'Met een Nederlands paspoort kun je als EU-burger vrij studeren en werken in andere EU-landen, waaronder Frankrijk.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/13/256994/Shutterstock_1626870589_v.png', null),
(12, 'Geschiedenis en Geografie', 'Welk land hoort niet bij de EU?', 'België', 'Griekenland', 'Marokko', 'C', 'Marokko is geen lid van de EU. De EU bestaat uitsluitend uit Europese landen. België en Griekenland zijn wél EU-leden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/14/256995/Shutterstock_2470455749_v.png', 1),
(13, 'Geschiedenis en Geografie', 'Wat gebeurde er tijdens de Holocaust?', 'Miljoenen Europese Joden werden vermoord.', 'Miljoenen Europese Joden werden naar Amerika gestuurd.', 'Miljoenen Europese Joden moesten vechten in het leger.', 'A', 'Tijdens de Holocaust (1941–1945) werden circa zes miljoen Europese Joden stelselmatig vermoord door de nazi''s.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/15/256996/Shutterstock_2434271509_v.png', null),
(14, 'Geschiedenis en Geografie', 'Wie was van 1940 tot 1945 de baas in Nederland?', 'een geallieerde', 'Duitsland', 'de Europese Unie', 'B', 'Van 1940 tot 1945 was Nederland bezet door nazi-Duitsland. De Nederlandse regering vluchtte naar Londen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/16/256997/Shutterstock_249573640_v.png', 1),
(15, 'Geschiedenis en Geografie', 'Welke wet is kort na de Tweede Wereldoorlog gemaakt?', 'Antisemitisme is strafbaar.', 'Naar Duitsland reizen is strafbaar.', 'Slavernij is strafbaar.', 'A', 'Na de Tweede Wereldoorlog werd antisemitisme strafbaar gesteld in Nederland als reactie op de Holocaust en de genocide op Joden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/17/256998/Shutterstock_2504799597_v.png', 1),
(16, 'Geschiedenis en Geografie', 'Wat houden in Zuidwest-Nederland het water tegen?', 'de polders', 'de molens', 'de Deltawerken', 'C', 'De Deltawerken zijn gebouwd na de watersnoodramp van 1953, waarbij grote delen van Zeeland en Zuid-Holland overstroomden. Ze beschermen Nederland tegen de zee.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/18/256999/Shutterstock_1904729224_v.png', null),
(17, 'Geschiedenis en Geografie', 'Welk land was vroeger een kolonie van Nederland?', 'Indonesië', 'Argentinië', 'India', 'A', 'Indonesië was tot 1945 een Nederlandse kolonie, bekend als Nederlands-Indië. In 1945 riep Indonesië zijn onafhankelijkheid uit.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/19/257000/Shutterstock_404697871_v.png', null),
(18, 'Geschiedenis en Geografie', 'Wanneer is de Nationale Dodenherdenking in Nederland?', 'op 27 april', 'op 4 mei', 'op 5 mei', 'B', 'Op 4 mei is de Nationale Dodenherdenking: Nederland herdenkt alle slachtoffers van de Tweede Wereldoorlog en andere conflicten.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/21/257002/Shutterstock_1768921946_v.png', null),
(19, 'Geschiedenis en Geografie', 'Wat wordt er gevierd met Keti Koti?', 'het einde van de koloniën', 'het einde van de Tweede Wereldoorlog', 'het einde van de slavernij', 'C', 'Keti Koti (1 juli) herdenkt de afschaffing van de slavernij in Suriname en de Nederlandse Antillen in 1863.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/22/257003/Shutterstock_107080052_v.jpg', null),
(20, 'Geschiedenis en Geografie', 'Waarom zijn de Deltawerken gebouwd?', 'Om meer vis te kunnen vangen', 'Om Nederland te beschermen tegen zee', 'Om nieuwe steden te kunnen bouwen', 'B', 'Na de watersnoodramp van 1953 bouwde Nederland de Deltawerken om zich te beschermen tegen overstromingen vanuit de zee.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180971753/23/257004/Shutterstock_2441597841_v.png', null),
(21, 'Geschiedenis en Geografie', 'Wanneer was de Holocaust?', 'Tijdens de Eerste Wereldoorlog.', 'Tijdens de Koude Oorlog.', 'Tijdens de Tweede Wereldoorlog.', 'C', 'De Holocaust vond plaats tijdens de Tweede Wereldoorlog (1940–1945), toen de nazi''s miljoenen Joden en anderen vermoordden.', null, 1),
(22, 'Geschiedenis en Geografie', 'Nederland is lid van de VN (Verenigde Naties). Wat is het doel van de VN?', 'Bescherming van de natuur.', 'Beter onderwijs.', 'Vrede en veiligheid.', 'C', 'De VN (Verenigde Naties) is een internationale organisatie opgericht in 1945 met als hoofddoel het bevorderen van vrede en veiligheid in de wereld.', null, null),
(23, 'Geschiedenis en Geografie', 'Waar ligt Amsterdam de hoofdstad van Nederland?', 'In de provincie Noord-Holland.', 'In de provincie Utrecht.', 'In de provincie Zuid-Holland.', 'A', 'Amsterdam is de hoofdstad van Nederland en ligt in de provincie Noord-Holland. Niet in Utrecht of Zuid-Holland.', null, null),
(24, 'Wonen', 'Aihan praat met de bank over een hypotheek. Wat is dat?', 'geld dat je van de bank leent om een woning te huren', 'geld dat je van de bank krijgt om een woning te kopen', 'geld dat je van de bank leent om een woning te kopen', 'C', 'Een hypotheek is geld dat je van de bank leent om een woning te kopen. Je betaalt dit bedrag in maandelijkse termijnen terug.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/3/257007/2566265775_v.png', null),
(25, 'Wonen', 'Wanneer schrijf je je in bij een woningcorporatie?', 'als je een woning wilt bouwen', 'als je een woning wilt kopen', 'als je een woning wilt huren', 'C', 'Bij een woningcorporatie schrijf je je in als je een huurwoning wilt. Een koopwoning of nieuwbouw regel je niet via de woningcorporatie.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/4/257008/2163241933_v.png', null),
(26, 'Wonen', 'Wat doet een makelaar?', 'Een makelaar helpt om een hypotheek te krijgen.', 'Een makelaar helpt om een koopwoning te vinden.', 'Een makelaar helpt om een huis te bouwen.', 'B', 'Een makelaar is een tussenpersoon die helpt bij het kopen of verkopen van woningen. Een hypotheek regelt de bank.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/5/257009/2562787943_v%20%281%29.png', 1),
(27, 'Wonen', 'Wat hoef je niet door te geven aan de gemeente?', 'Je gaat verhuizen.', 'Je hebt een nieuwe baan.', 'Je gaat samenwonen.', 'B', 'Een nieuwe baan hoef je niet door te geven aan de gemeente. Wel moet je verhuizingen, huwelijk of overlijden doorgeven.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/6/257010/2605545065_v.png', null),
(28, 'Wonen', 'Bartek wil graag een woning huren in de sociale huursector. Hoe heeft hij meer kans op een woning?', 'door veel geld te sparen', 'door zich op tijd in te schrijven bij de woningcorporatie', 'door een brief te sturen naar de woningcorporatie', 'B', 'In de sociale huursector zijn er wachtlijsten. Hoe eerder je je inschrijft bij de woningcorporatie, hoe meer kans je maakt op een woning.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/7/257011/2279682513_v.png', 1),
(29, 'Wonen', 'Mariam huurt een woning. Ze wil weten hoeveel huur ze betaalt. Waar kan ze dit vinden?', 'op de website van de woningcorporatie', 'in het huurcontract', 'op de website van de gemeente', 'B', 'In het huurcontract staan de afspraken tussen huurder en verhuurder, waaronder de huurprijs.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/8/257012/2055003308_v.png', null),
(30, 'Wonen', 'Diego huurt een woning. Het dak is kapot. De verhuurder wil het dak niet maken. Van wie kan Diego hulp krijgen?', 'de Huurcommissie en het Juridisch Loket', 'het Juridisch Loket en de gemeente', 'de gemeente en de Huurcommissie', 'A', 'De Huurcommissie lost geschillen op tussen huurder en verhuurder. Het Juridisch Loket geeft gratis juridisch advies.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/9/257013/1568981806_v.png', 1),
(31, 'Wonen', 'In een huurcontract staan de rechten en de plichten van een huurder. Wat zijn voorbeelden van de plichten van een huurder?', 'op tijd het water betalen en aardig zijn tegen de buren', 'op tijd het afval wegbrengen en de woning goed schoonmaken', 'op tijd de huur betalen en geen overlast geven', 'C', 'Als huurder ben je verplicht de huur op tijd te betalen en geen overlast te veroorzaken voor omwonenden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/10/257014/2146691817_v.png', null),
(32, 'Wonen', 'Feng heeft een koopwoning. Moet hij een opstalverzekering hebben?', 'Ja dat is verplicht voor alle mensen met een koopwoning.', 'Ja dat is verplicht voor iedereen vanaf 18 jaar.', 'Nee dat is niet verplicht.', 'A', 'Voor een koopwoning is een opstalverzekering verplicht. Deze dekt schade aan het gebouw zelf, zoals bij brand of storm.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/11/257015/1033199560_v.png', null),
(33, 'Wonen', 'Kumar heeft recht op huurtoeslag. Hoe kan hij huurtoeslag krijgen?', 'Hij moet dit bij Dienst Toeslagen aanvragen.', 'Iemand van de gemeente moet dit voor hem aanvragen.', 'Hij moet dit bij de gemeente aanvragen.', 'A', 'Huurtoeslag moet je zelf aanvragen bij Dienst Toeslagen (onderdeel van de Belastingdienst). Het wordt niet automatisch toegekend.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/12/257016/1936245112_v.png', null),
(34, 'Wonen', 'Wat is een WA-verzekering?', 'een verplichte verzekering als je een auto motor of scooter hebt', 'een verplichte verzekering voor iedereen met een eigen woning', 'een verplichte verzekering als je werkt', 'A', 'Een WA-verzekering (wettelijke aansprakelijkheidsverzekering voertuig) is verplicht als je een auto, motor of scooter hebt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/13/257017/1965899473_v.png', 1),
(35, 'Wonen', 'Mahmoud heeft een woning gekocht. Hij heeft nog geen internetabonnement. Hoe kan hij internet krijgen in zijn woning?', 'Hij hoeft niets te doen. Hij krijgt een abonnement bij de woning.', 'Hij sluit zelf een abonnement af bij een provider.', 'Hij vraagt internet aan bij de gemeente.', 'B', 'Internet sluit je zelf af door een abonnement te kiezen bij een provider. De verhuurder of gemeente regelt dit niet voor je.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/14/257018/1180890430_v.png', null),
(36, 'Wonen', 'Nuria heeft een energiecontract met een variabel tarief. Wat is dat?', 'Het bedrag voor energie wordt hoger of lager tijdens het energiecontract.', 'Het bedrag voor energie wordt elke maand een beetje lager.', 'Het bedrag voor energie blijft elke maand hetzelfde.', 'A', 'Bij een variabel tarief schommelt de prijs van energie mee met de marktprijs. Je energierekening kan dus hoger of lager worden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/15/257019/2493918251_v.png', 1),
(37, 'Wonen', 'Wouter heeft een leeg blikje met statiegeld. Waar kan hij dit blikje inleveren?', 'Bij de apotheek', 'Bij de gemeente', 'Bij de supermarkt', 'C', 'Lege blikjes met statiegeld kun je inleveren bij de supermarkt. Je krijgt dan het betaalde statiegeld terug.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/16/257020/2605190127_v.png', null),
(38, 'Wonen', 'Job en Kelly willen een huis kopen. Wie kan ze daarbij helpen?', 'een uitzendbureau', 'een makelaar', 'het UWV', 'B', 'Een makelaar helpt bij het vinden en kopen of verkopen van een woning. Een hypotheekadviseur helpt bij de financiering.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/17/257021/1734027209_v.png', null),
(39, 'Wonen', 'Marieke heeft een laag inkomen. Veel huizen zijn te duur voor haar. Hoe kan ze toch een woning betalen?', 'Ze kan een woning huren in de sociale huursector.', 'Ze kan een woning huren in de vrije huursector.', 'Ze kan een woning kopen.', 'A', 'De sociale huursector biedt betaalbare huurwoningen voor mensen met een lager inkomen. Er is wel een wachtlijst.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/18/257022/2484239545_v.png', null),
(40, 'Wonen', 'Waarom moet je afval scheiden?', 'Dan krijg je meer statiegeld terug.', 'Dan kan een deel van het afval gerecycled worden.', 'Dan houd je meer restafval over.', 'B', 'Door afval te scheiden (papier, glas, GFT, plastic) kan een deel worden gerecycled, wat goed is voor het milieu.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/19/257023/2470794029_v.png', null),
(41, 'Wonen', 'Wanneer wordt het afval opgehaald?', 'Dat is per gemeente verschillend.', 'Dat is per week verschillend.', 'Dat is per provincie verschillend.', 'A', 'Elke gemeente heeft zijn eigen schema voor het ophalen van afval. Kijk in uw gemeentegids of op de website van de gemeente.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/20/257024/2027019419_v.png', null),
(42, 'Wonen', 'Lauren en Luc zijn niet getrouwd. Ze willen gaan samenwonen. Mag dat in Nederland?', 'Ja dat mag.', 'Alleen als de gemeente toestemming geeft.', 'Nee dat mag niet.', 'A', 'In Nederland is samenwonen zonder trouwen volledig legaal. Er zijn geen wettelijke beperkingen voor ongehuwd samenwonen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/22/257026/1835861686_v.png', null),
(43, 'Wonen', 'Wat staat niet in de Nederlandse wet?', 'In plaats van trouwen kun je ook kiezen voor een geregistreerd partnerschap.', 'Alleen een man en een vrouw kunnen met elkaar trouwen.', 'Je moet minimaal 18 jaar zijn om te trouwen.', 'B', 'In Nederland is het huwelijk voor iedereen toegankelijk, ook voor mensen van hetzelfde geslacht. De wet bepaalt geen geslachtsbeperking.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180828909/23/257027/670100347_v.png', null),
(44, 'Wonen', 'Je hebt een aansprakelijkheidsverzekering. Wanneer kun je die gebruiken?', 'Je stoot een lamp om bij de buren. De lamp is kapot.', 'De lamp van de buren is gestolen.', 'Door brand is je lamp kapot gegaan.', 'A', 'Een aansprakelijkheidsverzekering (WA) dekt schade die jij per ongeluk bij anderen veroorzaakt, zoals een omgevallen lamp bij de buren.', null, null),
(45, 'Wonen', 'Welk afval mag je niet in de vuilnisbak gooien?', 'Plastic', 'Chemisch', 'Rest', 'B', 'Chemisch afval (zoals batterijen, verf en medicijnen) mag niet in de gewone vuilnisbak. Dit breng je naar het chemokar of milieustraat.', null, null),
(46, 'Wonen', 'Anna heeft een energierekening gekregen. Waarom krijgt zij ieder jaar een jaarrekening?', 'om te zien hoeveel geld je terugkrijgt of moet betalen', 'om te zien hoeveel de televisie kost', 'om meer energie te krijgen', 'A', 'De jaarrekening laat zien hoeveel energie je werkelijk hebt gebruikt. Als je te veel hebt betaald, krijg je geld terug; anders betaal je bij.', null, null),
(47, 'Wonen', 'Je wilt gas en elektriciteit aanvragen. Hoe doe je dat?', 'Er is maar één energiebedrijf. Ik meld me daar aan.', 'Ik kies een energiebedrijf. Ik meld me daar aan.', 'Er is maar één waterbedrijf. Ik meld me daar aan.', 'B', 'Gas en elektriciteit sluit je zelf af door een energiebedrijf te kiezen en je daar aan te melden via hun website of telefoon.', null, null),
(48, 'Wonen', 'Je kraan is kapot. Er lekt water uit. De kraan moet gemaakt worden. Wie bel je?', 'een installateur', 'het waterbedrijf', 'een loodgieter', 'C', 'Een loodgieter repareert leidingen, kranen en sanitair. Voor elektrische problemen bel je een elektricien.', null, null),
(49, 'Wonen', 'De familie Smit wil een huis huren. Ze weten niet welke huizen ze kunnen huren. Wat moeten ze doen?', 'Ze moeten op internet zoeken.', 'Ze doen niks. Ze krijgen een brief over welke huizen ze kunnen huren.', 'Ze moeten de gemeente bellen.', 'A', 'Je kunt huurwoningen vinden via websites zoals Funda, Pararius of de site van woningcorporaties.', null, null),
(50, 'Wonen', 'Je wilt water aanvragen. Hoe doe je dat?', 'Er is maar één waterbedrijf. Ik meld me daar aan.', 'Ik kies een waterbedrijf. Ik meld me daar aan.', 'Er is maar één energiebedrijf. Ik meld me daar aan.', 'A', 'In Nederland is er per regio slechts één waterbedrijf. Je meldt je aan bij dat regionale waterbedrijf voor een wateraansluiting.', null, null),
(51, 'Wonen', 'Het heeft hard gestormd vannacht. Er is een boom gevallen op het dak van Annemiekes huis. Wat moet Annemieke doen als ze schade heeft?', 'Ze moet dan snel een verzekering afsluiten.', 'Ze moet dan premie gaan betalen.', 'Ze moet de schade melden bij de verzekeringsmaatschappij.', 'C', 'Bij schade aan je woning (zoals door een storm) moet je dit melden bij je verzekeringsmaatschappij om vergoeding te ontvangen.', null, null),
(52, 'Wonen', 'Iemand heeft Peters computer en televisie gestolen. Peter is gelukkig verzekerd tegen diefstal. Welke verzekering betaalt dit?', 'de opstalverzekering', 'de inboedelverzekering', 'de aansprakelijkheidsverzekering', 'B', 'De inboedelverzekering dekt gestolen of beschadigde spullen in je woning, zoals een computer of televisie.', null, null),
(53, 'Wonen', 'Erik woont in een sociale huurwoning. Wat is dat?', 'Een woning met een maximum prijs', 'Een woning voor een korte tijd', 'Een woning zonder huurcontract', 'A', 'Een sociale huurwoning heeft een huurprijs onder de liberalisatiegrens. Woningcorporaties verhuren deze woningen aan mensen met een lager inkomen.', null, null),
(54, 'Wonen', 'Peter zoekt een huurhuis. Waar kan hij zich inschrijven als woningzoekende?', 'Bij een uitzendbureau.', 'Bij een woningcorporatie.', 'Bij het UWV.', 'B', 'Als woningzoekende schrijf je je in bij een woningcorporatie. Zij beheren de sociale huurwoningen.', null, null),
(55, 'Wonen', 'Layla is 18 jaar oud. Ze wil een huis huren. Wat moet ze doen?', 'Het huis kopen via de bank.', 'Naar een makelaar gaan.', 'Het huurcontract ondertekenen.', 'C', 'Als je een woning wilt huren, moet je een huurcontract tekenen. Je bent 18 jaar en daarmee juridisch handelingsbekwaam.', null, null),
(56, 'Wonen', 'Nancy huurt een woning. De dakgoot is stuk. Wie moet dit repareren?', 'Tania zelf.', 'De verhuurder.', 'De gemeente.', 'B', 'Groot onderhoud, zoals een kapotte dakgoot, is de verantwoordelijkheid van de verhuurder. Klein onderhoud is voor de huurder.', null, null),
(57, 'Wonen', 'Ibrahim huurt een woning. Hij wil verhuizen. Hoe lang van tevoren moet hij dit zeggen?', 'Een dag.', 'Een week.', 'Een maand.', 'C', 'In Nederland moet je minstens één maand opzegtermijn aanhouden als je een huurwoning wilt verlaten.', null, null),
(58, 'Wonen', 'Nora huurt een woning. Haar huur gaat omhoog. Wat kan ze doen?', 'Meteen verhuizen.', 'Naar het huurcommissie gaan.', 'Niets, ze moet betalen.', 'B', 'Als je het niet eens bent met een huurverhoging, kun je naar de Huurcommissie gaan. Zij beoordelen of de verhoging terecht is.', null, null),
(59, 'Wonen', 'Eva koopt een huis. Wie helpt haar met het onderzoeken van het huis?', 'De makelaar.', 'De KNCV.', 'Een keurmeester.', 'C', 'Een bouwkundige keurmeester inspecteert de technische staat van een woning vóór de aankoop om verborgen gebreken op te sporen.', null, null),
(60, 'Wonen', 'Niels koopt een huis met een schuld. Wat is dit?', 'Een erfenis.', 'Een hypotheek.', 'Een donatie.', 'B', 'Een hypotheek is een lening van de bank waarmee je een huis koopt. Je betaalt maandelijks rente en aflossing.', null, null),
(61, 'Wonen', 'Wendy spaart geld om een huis te kopen. Waar kan zij best sparen?', 'In een la.', 'Bij de bank.', 'Bij vrienden.', 'B', 'Sparen doe je het veiligst bij een bank. Je spaargeld staat veilig en je ontvangt rente.', null, null),
(62, 'Wonen', 'Lars is eigenaar van zijn huis. Hij moet belasting betalen. Wat is dit?', 'Erfbelasting.', 'Onroerende zaakbelasting.', 'Omzetbelasting.', 'B', 'Eigenaren van onroerend goed betalen onroerendezaakbelasting (OZB) aan de gemeente. Dit is een belasting op de waarde van de woning.', null, null),
(63, 'Wonen', 'Remco huurt een woning in het buitenland. Waar moet hij zich inschrijven?', 'Bij de politie.', 'Bij de gemeente.', 'Bij de bank.', 'B', 'Als je in het buitenland woont, moet je je inschrijven bij de gemeente (in de BRP) van je nieuwe woonplaats.', null, null),
(64, 'Wonen', 'Suzan huurt een woning. Ze betaalt huur voor het hele jaar vooruit. Is dit normaal?', 'Ja, dat is normaal.', 'Nee, je betaalt per maand.', 'Nee, je betaalt per week.', 'B', 'Huur betaal je normaal gesproken per maand. Een heel jaar vooruitbetalen is ongebruikelijk en niet verplicht.', null, null),
(65, 'Wonen', 'Elin is eigenaar van een woning. Ze verhuurt kamers. Wat kan ze doen als de huurder niet betaalt?', 'Hem uit de woning zetten.', 'Naar de rechter gaan.', 'De politie bellen.', 'B', 'Als een huurder niet betaalt, kan de verhuurder naar de rechter stappen om de huur of ontruiming af te dwingen.', null, null),
(66, 'Wonen', 'Lara koopt een huis. Ze leent geld van de bank. Wat heet dit?', 'Een schuld.', 'Een hypotheek.', 'Een spaarrekening.', 'B', 'Een hypotheek is het geld dat je van de bank leent om een huis te kopen. Je betaalt dit bedrag over meerdere jaren terug.', null, 1),
(67, 'Wonen', 'André huurt een kamer. De woning is niet schoon. Wat kan hij doen?', 'De huur niet betalen.', 'Met de verhuurder spreken.', 'Meteen verhuizen.', 'B', 'Als je een probleem hebt met de woning of de verhuurder, bespreek je dit eerst met de verhuurder zelf voor je verdere stappen neemt.', null, null),
(68, 'Wonen', 'Daan wil zijn huis verkopen. Wie helpt hem daarmee?', 'De gemeente.', 'Een makelaar.', 'De bank.', 'B', 'Een makelaar begeleidt het verkoopproces: waardebepaling, bezichtigingen, onderhandelen en de overdracht.', null, null),
(69, 'Wonen', 'Femke koopt een woning. Wat moet ze van de bank krijgen?', 'Een spaarrekening.', 'Een hypotheek.', 'Een persoonsloon.', 'B', 'Om een huis te kopen heb je normaal gesproken een hypotheek (lening) van de bank nodig, tenzij je het contant kunt betalen.', null, null),
(70, 'Wonen', 'Wouter heeft een leeg blikje met statiegeld. Waar kan hij dit blikje inleveren?', 'Bij de apotheek.', 'Bij de gemeente.', 'Bij een supermarkt.', 'C', 'Lege blikjes met statiegeld lever je in bij de supermarkt. Je ontvangt dan de statiegeldwaarde terug.', null, null),
(71, 'Wonen', 'Job en Kelly willen een huis kopen. Wie kan ze daarbij helpen?', 'Een uitzendbureau.', 'Een makelaar.', 'Het UWV.', 'B', 'Een makelaar helpt bij het vinden van een koopwoning, de onderhandelingen en het regelen van de overdracht.', null, null),
(72, 'Wonen', 'Erik woont in een sociale huurwoning. Wat is dat?', 'Een woning met een maximum huurprijs.', 'Een woning voor een korte tijd.', 'Een woning zonder huurcontract.', 'A', 'Sociale huurwoningen hebben een maximale huurprijs (de liberalisatiegrens). Ze zijn bedoeld voor mensen met een lager inkomen.', null, null),
(73, 'Wonen', 'William en Kyra zijn getrouwd. Ze willen gaan samenwonen. Mag dat in Nederland?', 'Ja dat mag.', 'Alleen met een samenlevingscontract.', 'Nee dat mag niet.', 'A', 'In Nederland mogen gehuwden en ongehuwde stellen samenwonen. Er zijn geen wettelijke beperkingen voor samenwonen.', null, null),
(74, 'Gezondheid en Gezondheidszorg', 'De baby van Aihan komt pas over zes maanden maar ze moet nu alvast dingen regelen voor na de bevalling. Wat kan ze al voor de bevalling regelen?', 'Ze kan haar baby aangeven bij de gemeente.', 'Ze kan een afspraak bij het consultatiebureau maken.', 'Ze kan zich aanmelden voor kraamzorg.', 'C', 'Kraamzorg moet je vóór de bevalling aanvragen. De gemeente aangeven en consultatiebureau maak je na de geboorte.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/3/257030/KNMB1_th03_p08_e001_q003.mp3', null),
(75, 'Gezondheid en Gezondheidszorg', 'Lauren is acht weken zwanger. Bij wie kan ze een afspraak maken voor controle?', 'bij de verloskundige', 'bij de praktijkondersteuner', 'bij de gynaecoloog', 'A', 'In Nederland is de verloskundige het eerste aanspreekpunt bij een normale zwangerschap. Bij complicaties verwijst zij door naar de gynaecoloog.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/4/257031/KNMB1_th03_p08_e001_q004.mp3', null),
(76, 'Gezondheid en Gezondheidszorg', 'Diego gaat naar de huisarts. Moet hij de rekening van de huisarts zelf betalen?', 'Ja hij moet de rekening zelf betalen.', 'Nee de zorgverzekering betaalt de rekening.', 'Nee maar hij betaalt wel een eigen risico.', 'B', 'De huisarts is gratis via de basisverzekering. Het eigen risico geldt niet voor de huisarts.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/5/257032/KNMB1_th03_p08_e001_q005.mp3', null),
(77, 'Gezondheid en Gezondheidszorg', 'Lars krijgt zorgtoeslag. Hij heeft een nieuwe baan met een hoger inkomen. Moet hij dit doorgeven aan Dienst Toeslagen?', 'Ja dat moet aan het einde van het jaar.', 'Ja dat moet zo snel mogelijk.', 'Nee dat doet de baas van Lars.', 'B', 'Wijzigingen in je inkomen moet je zo snel mogelijk doorgeven aan Dienst Toeslagen, anders ontvang je te veel of te weinig toeslag.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/6/257033/KNMB1_th03_p08_e001_q006.mp3', null),
(78, 'Gezondheid en Gezondheidszorg', 'Luc wil van zorgverzekeraar wisselen. Kan dat in Nederland?', 'Ja hij kan één keer per jaar wisselen.', 'Misschien dat moet hij eerst aan zijn huisarts vragen.', 'Nee hij kan niet wisselen van zorgverzekeraar.', 'A', 'In Nederland mag je elk jaar van zorgverzekeraar wisselen, maar alleen in de overstapperiode (november-december).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/7/257034/KNMB1_th03_p08_e001_q007.mp3', null),
(79, 'Gezondheid en Gezondheidszorg', 'Mahmoud haalt medicijnen bij de apotheek. De medewerker van de apotheek zegt: ''U betaalt voor deze medicijnen een eigen bijdrage.'' Wat betekent dat?', 'Hij moet een deel van de kosten zelf betalen.', 'De zorgverzekering betaalt zijn medicijnen.', 'Hij kan een deel van de kosten declareren bij de zorgverzekeraar.', 'A', 'Een eigen bijdrage betekent dat je zelf een deel van de medicijnkosten betaalt, bovenop wat de verzekering vergoedt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/8/257035/KNMB1_th03_p08_e001_q008.mp3', null),
(80, 'Gezondheid en Gezondheidszorg', 'Marieke heeft een afspraak in het ziekenhuis. De arts zegt: ''U moet een deel van de kosten zelf betalen.'' Waarom is dat?', 'Voor het ziekenhuis moet je een eigen risico betalen.', 'Ze heeft een hoog inkomen.', 'Ze heeft geen zorgverzekering.', 'A', 'Het eigen risico is het bedrag dat je zelf betaalt voor zorgkosten in het ziekenhuis, voordat de verzekering bijdraagt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/9/257036/KNMB1_th03_p08_e001_q009.mp3', null),
(81, 'Gezondheid en Gezondheidszorg', 'Mert heeft een aanvullende verzekering. Welke zorg wordt uit een aanvullende verzekering vergoed?', 'de huisarts', 'de fysiotherapeut', 'de psycholoog', 'B', 'De aanvullende verzekering vergoedt zorg die niet in het basispakket zit, zoals fysiotherapie, brillen of extra tandheelkunde.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/10/257037/KNMB1_th03_p08_e001_q010.mp3', 1),
(82, 'Gezondheid en Gezondheidszorg', 'Nuria betaalt haar eigen risico gespreid. Wat betekent dat?', 'Ze betaalt elke maand een deel van het bedrag.', 'Ze sluit een aanvullende verzekering af.', 'Ze vraagt zorgtoeslag aan.', 'A', 'Gespreid eigen risico betalen betekent dat je het jaarlijkse eigen risico in maandelijkse termijnen betaalt in plaats van in één keer.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/11/257038/KNMB1_th03_p08_e001_q011.mp3', 1),
(83, 'Gezondheid en Gezondheidszorg', 'Feng wil zich inschrijven bij een tandarts. Waar kan dat?', 'bij een tandarts in de buurt', 'bij de gemeente', 'bij een zorgverzekeraar', 'A', 'Je schrijft je zelf in bij een tandarts in je buurt. Er is geen verwijzing van de huisarts nodig.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/12/257039/KNMB1_th03_p08_e001_q012.mp3', null),
(84, 'Gezondheid en Gezondheidszorg', 'Het is woensdagavond. De baby van Sama heeft hoge koorts. Sama wil met haar baby naar de dokter. Wie moet ze bellen?', 'de huisartsenpraktijk', 'de huisartsenpost', 'het ziekenhuis', 'B', 'Buiten kantooruren van de huisarts bel je de huisartsenpost (HAP) voor spoedeisende maar niet levensbedreigende situaties.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/13/257040/KNMB1_th03_p08_e001_q013.mp3', 1),
(85, 'Gezondheid en Gezondheidszorg', 'Wat kan een tolk doen bij een bezoek aan de huisarts?', 'helpen als iemand niet goed Nederlands spreekt', 'helpen met medicijnen voorschrijven', 'helpen als iemand depressief is', 'A', 'Een tolk helpt mensen die het Nederlands niet goed beheersen bij gesprekken met zorgverleners.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/14/257041/KNMB1_th03_p08_e001_q014.mp3', null),
(86, 'Gezondheid en Gezondheidszorg', 'Kumar gaat naar de apotheek voor medicijnen. Wat moet hij meenemen?', 'een verwijsbrief', 'de pas van zijn zorgverzekering', 'een recept', 'C', 'Voor medicijnen heb je een recept van de huisarts of specialist nodig. Zonder recept geeft de apotheek de medicijnen niet af.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/15/257042/KNMB1_th03_p08_e001_q015.mp3', null),
(87, 'Gezondheid en Gezondheidszorg', 'Meneer de Boer (80 jaar) kan niet meer traplopen. Hij kan zich ook niet zelf wassen. Zijn kinderen wonen ver weg. Wie kan meneer de Boer helpen?', 'de gemeente', 'het ziekenhuis', 'de zorgverzekeraar', 'A', 'Voor thuiszorg en hulp bij dagelijkse activiteiten (zoals wassen of eten) kun je bij de gemeente terecht via de WMO-regeling.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/16/257043/KNMB1_th03_p08_e001_q016.mp3', null),
(88, 'Gezondheid en Gezondheidszorg', 'Mert voelt zich al een aantal weken depressief. Hij zoekt hulp. Wat kan hij doen?', 'de huisarts bellen', 'de specialist bellen', 'het ziekenhuis bellen', 'A', 'Bij klachten zoals depressie of burn-out is de huisarts het eerste aanspreekpunt. Hij kan je doorverwijzen naar een psycholoog.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/17/257044/KNMB1_th03_p08_e001_q017.mp3', null),
(89, 'Gezondheid en Gezondheidszorg', 'Toby is doorverwezen naar de fysiotherapeut. De fysiotherapeut wil meer informatie over de gezondheid van Toby. Mag de huisarts deze informatie met de fysiotherapeut delen?', 'Alleen als het levensbedreigend is.', 'Alleen als Toby toestemming geeft.', 'Nee dat is geheim.', 'B', 'De huisarts mag medische informatie alleen delen met andere zorgverleners als de patiënt hier toestemming voor geeft (privacy).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/18/257045/KNMB1_th03_p08_e001_q018.mp3', null),
(90, 'Gezondheid en Gezondheidszorg', 'Zeynep heeft vaak last van haar longen. Ze wil naar een specialist in het ziekenhuis. Wat heeft ze nodig?', 'een verwijsbrief van de huisarts', 'een (herhaal)recept', 'niets', 'A', 'Je hebt een verwijsbrief (doorverwijzing) van de huisarts nodig voordat je naar een specialist in het ziekenhuis kunt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/19/257046/KNMB1_th03_p08_e001_q019.mp3', null),
(91, 'Gezondheid en Gezondheidszorg', 'Samuel vult geen keuze in het Donorregister in. Bij zijn naam staat nu ''geen bezwaar''. Wat betekent dat?', 'dat hij orgaandonor is', 'dat hij geen orgaandonor is', 'dat de arts beslist of hij orgaandonor is', 'A', 'Wie geen keuze invult in het Donorregister, krijgt automatisch de status ''geen bezwaar'', wat betekent dat men orgaandonor is.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/20/257049/KNMB1_th03_p08_e001_q020.mp3', 1),
(92, 'Gezondheid en Gezondheidszorg', 'De collega van Marie heeft een baby gekregen. Marie gaat op bezoek. Wat hoort bij een geboorte in Nederland?', 'beschuit met muisjes', 'een Nederlandse vlag aan het huis', 'bloemen aan de deur van het huis', 'A', 'Bij een geboorte in Nederland is het traditie om beschuit met roze of blauwe muisjes uit te delen (voor een meisje of jongen).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/22/257049/KNMB1_th03_p08_e001_q022.mp3', null),
(93, 'Gezondheid en Gezondheidszorg', 'Yana heeft een afspraak bij de tandarts. Ze is 15 minuten te laat. Wat kan ze doen?', 'de tandarts bellen', 'thuis blijven en wachten tot de tandarts belt', 'wachten in de wachtkamer van de tandartspraktijk', 'C', 'Als je te laat bent voor een tandartsenafspraak, meld je je bij de receptie. Je wacht in de wachtkamer totdat de tandarts je kan ontvangen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180832354/23/257050/KNMB1_th03_p08_e001_q023.mp3', null),
(94, 'Gezondheid en Gezondheidszorg', 'Ali is verhuisd. Hoe krijgt hij een huisarts in zijn nieuwe woonplaats?', 'De gemeente regelt een huisarts voor hem.', 'De huisarts in de wijk stuurt hem een bericht.', 'Ramish zoekt zelf een huisarts.', 'C', 'Als je verhuist, zoek je zelf een huisarts in je nieuwe woonplaats en schrijf je je in bij die praktijk.', null, null),
(95, 'Gezondheid en Gezondheidszorg', 'Anne heeft erge keelpijn. Ze wil naar een dokter. Het is maandagochtend. Waar moet Eline een afspraak maken?', 'Bij de apotheek.', 'Bij de huisarts.', 'Bij de spoedeisende hulp.', 'B', 'Op maandagochtend is de huisartsenpraktijk open. Voor keelpijn of andere gewone klachten ga je naar de huisarts.', null, null),
(96, 'Gezondheid en Gezondheidszorg', 'De collega van Evy ligt op de grond. Hij beweegt niet. Welk nummer moet zij bellen?', 'Het alarmnummer 112.', 'Het nummer van de huisarts.', 'Het nummer van het ziekenhuis.', 'A', 'Bij een noodsituatie (iemand die niet beweegt) bel je altijd 112, het algemene alarmnummer voor politie, brandweer en ambulance.', null, null),
(97, 'Gezondheid en Gezondheidszorg', 'Mariam heeft een baby gekregen. Wat doet het consultatiebureau voor Nora en haar baby?', 'De gezondheid van de baby controleren.', 'Een oppas regelen als Nora weg moet.', 'Helpen bij het huishouden.', 'A', 'Het consultatiebureau (CJG) controleert de groei en gezondheid van baby''s en jonge kinderen en geeft vaccinaties.', null, null),
(98, 'Gezondheid en Gezondheidszorg', 'Mohemmed krijgt een bloedonderzoek. Zijn verzekering zegt dat het bloedonderzoek onder zijn eigen risico valt. Wat betekent dat?', 'De overheid betaalt de kosten.', 'De verzekering betaalt de kosten.', 'Peter betaalt de kosten.', 'C', 'Als een behandeling onder je eigen risico valt, betaal je die kosten zelf totdat je het eigenrisicobedrag bereikt.', null, 1),
(99, 'Gezondheid en Gezondheidszorg', 'Rob is bij de apotheek. Hij komt medicijnen voor zijn hart halen. Wat heeft de apotheek nodig om de medicijnen af te geven?', 'Een recept van de dokter.', 'Zijn DigiD.', 'Zijn verzekeringspapieren.', 'A', 'De apotheek geeft alleen op recept medicijnen af. Een recept is een schriftelijke opdracht van een arts.', null, 1),
(100, 'Gezondheid en Gezondheidszorg', 'Els is verhuisd en heeft een nieuwe huisarts. Haar nieuwe huisarts wil informatie over de gezondheidsgeschiedenis van Els. Mag de oude huisarts dit zomaar doorgeven?', 'Ja dat mag meteen.', 'Alleen als Els toestemming geeft.', 'Nee die informatie is geheim.', 'B', 'Medische informatie is vertrouwelijk. Een arts mag je dossier alleen overdragen aan een andere arts met jouw toestemming.', null, 1),
(101, 'Gezondheid en Gezondheidszorg', 'Eva ziet een grote brand. Welk telefoonnummer moet zij bellen?', '112', '666', '779', 'A', 'Bij brand of een ernstig ongeluk bel je 112, het landelijke alarmnummer voor spoedeisende hulp.', null, null),
(102, 'Gezondheid en Gezondheidszorg', 'Paul is verhuisd en wil een nieuwe tandarts. Wie regelt de nieuwe tandarts voor Paul?', 'De gemeente.', 'De zorgverzekeraar.', 'Paul zelf.', 'C', 'Je regelt zelf een nieuwe tandarts door contact op te nemen met een tandartspraktijk in je buurt.', null, null),
(103, 'Gezondheid en Gezondheidszorg', 'Nadia gaat naar een Nederlandse huisarts. Ze spreekt geen Nederlands. Ze heeft niemand die kan vertalen. Wat moet de huisarts doen?', 'Een tolk regelen voor Nadia.', 'Nadia naar een ziekenhuis sturen.', 'Nederlands praten met Nadia.', 'A', 'Bij een taalbarrière is de huisarts verplicht een tolk in te schakelen zodat de patiënt goede zorg ontvangt.', null, null),
(104, 'Onderwijs en Opvoeding', 'De dochter van Bartek luistert niet goed naar hem. Waar kan hij hulp krijgen?', 'bij jeugdzorg en het CJG', 'bij de verloskundige en de gynaecoloog', 'op school en bij de BSO', 'C', 'Op school en bij de BSO (buitenschoolse opvang) zijn professionals die kunnen helpen bij opvoedingsvragen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/3/257053/KNMB1_th04_p07_e001_q003.mp3', null),
(105, 'Onderwijs en Opvoeding', 'Mahmoud is 15 jaar. Tijdens het voetballen maakt hij een raam kapot. Wie is er aansprakelijk voor de kosten?', 'de ouders van Mahmoud', 'Mahmoud', 'de huurders van het huis', 'A', 'Minderjarigen (onder de 18 jaar) zijn wettelijk niet aansprakelijk; hun ouders zijn verantwoordelijk voor de schade die zij veroorzaken.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/4/257054/KNMB1_th04_p07_e001_q004.mp3', null),
(106, 'Onderwijs en Opvoeding', 'De dochter van Nuria gaat naar het kinderdagverblijf. Wat doet ze hier niet?', 'Ze leert lezen en schrijven.', 'Ze bereidt zich voor op de basisschool.', 'Ze zingt en speelt met andere kinderen.', 'A', 'Op het kinderdagverblijf spelen en socialiseren kinderen. Lezen en schrijven leren kinderen pas op de basisschool.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/5/257055/KNMB1_th04_p07_e001_q005.mp3', null),
(107, 'Onderwijs en Opvoeding', 'Er is in Nederland een leerplicht en een kwalificatieplicht. Voor welke leeftijd is de leerplicht?', 'van 5 tot 16 jaar van 4 tot 18 jaar', 'van 5 tot 16 jaar', 'van 16 tot 18 jaar', 'B', 'De leerplicht in Nederland geldt van 5 tot 16 jaar. De kwalificatieplicht loopt tot 18 jaar voor kinderen zonder startkwalificatie.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/6/257056/KNMB1_th04_p07_e001_q006.mp3', null),
(108, 'Onderwijs en Opvoeding', 'Er zijn in Nederland verschillende scholen. Wat is de goede volgorde?', 'het kinderdagverblijf - de basisschool - de middelbare school', 'de basisschool - het kinderdagverblijf - de middelbare school', 'de middelbare school - het kinderdagverblijf - de basisschool', 'A', 'De juiste volgorde in het Nederlandse onderwijssysteem is: kinderdagverblijf → basisschool → middelbare school.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/7/257057/KNMB1_th04_p07_e001_q007.mp3', null),
(109, 'Onderwijs en Opvoeding', 'Wat is het speciaal onderwijs?', 'scholen voor kinderen die meer hulp nodig hebben zoals dove en blinde kinderen', 'scholen die één onderwerp heel belangrijk vinden zoals sport', 'scholen met een religie zoals de islam', 'A', 'Het speciaal onderwijs is bedoeld voor kinderen met een beperking of speciale onderwijsbehoefte, zoals dove, blinde of meervoudig gehandicapte kinderen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/8/257058/KNMB1_th04_p07_e001_q008.mp3', 1),
(110, 'Onderwijs en Opvoeding', 'De dochter van Yana moet op maandag om 11.00 uur naar de tandarts. Het is geen vakantie. Mag Yana met haar dochter naar de tandarts?', 'Ja dat mag.', 'Alleen als de school toestemming geeft.', 'Nee want ze heeft leerplicht.', 'A', 'Ouders mogen hun kind van school halen voor een doktersbezoek of tandarts, ook als het geen vakantie is. Dit is toegestaan.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/9/257059/KNMB1_th04_p07_e001_q009.mp3', null),
(111, 'Onderwijs en Opvoeding', 'Lars wil met zijn kinderen op reis. Het is nog geen vakantie. Mag Lars met zijn kinderen op reis?', 'Ja dat mag.', 'Alleen als de school toestemming geeft.', 'Nee want het is geen vakantie.', 'B', 'Vakantie buiten de schoolvakanties is alleen toegestaan met toestemming van de directeur en alleen in bijzondere omstandigheden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/10/257060/KNMB1_th04_p07_e001_q010.mp3', null),
(112, 'Onderwijs en Opvoeding', 'Scholen kunnen sommige vrije dagen zelf kiezen. Met welke feestdagen kunnen scholen zelf kiezen of ze dicht zijn?', 'carnaval en Eid-al-Fitr', 'kerst en oud en nieuw', 'Pasen en Hemelvaart', 'A', 'Scholen mogen zelf kiezen of ze vrij zijn op carnaval en Eid al-Fitr. Officiële nationale feestdagen zijn verplicht vrij.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/11/257061/KNMB1_th04_p07_e001_q011.mp3', 1),
(113, 'Onderwijs en Opvoeding', 'Een juf vindt dat de ontwikkeling van een leerling niet goed gaat. Wanneer kan ze dit het beste met de ouders bespreken?', 'in de pauze', 'als de ouders het kind komen ophalen', 'tijdens een 10 minutengesprek', 'C', 'Een tien-minutengesprek is een kort gesprek tussen ouders en de leraar om de voortgang en het welzijn van het kind te bespreken.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/12/257062/KNMB1_th04_p07_e001_q012.mp3', null),
(114, 'Onderwijs en Opvoeding', 'In Nederland helpen ouders vaak op de school van hun kinderen. Hoe kunnen de ouders op school helpen?', 'Ze kunnen meegaan op schoolreisje of helpen met activiteiten in de klas.', 'Ze kunnen het gebouw verven en trakteren.', 'Ze kunnen de kinderen stil houden en lesgeven over rekenen en schrijven.', 'A', 'Ouderparticipatie op school (meehelpen bij uitjes of in de klas) wordt in Nederland gestimuleerd en gewaardeerd.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/13/257063/KNMB1_th04_p07_e001_q013.mp3', null),
(115, 'Onderwijs en Opvoeding', 'Kumar is 16 jaar. Hij is klaar met het vmbo op de middelbare school. Wat kan hij nu doen?', 'Hij moet nog een opleiding volgen want hij heeft kwalificatieplicht.', 'Hij kan werken of een opleiding volgen.', 'Hij moet werken want hij mag geen opleiding meer volgen.', 'A', 'De kwalificatieplicht verplicht jongeren van 16 en 17 jaar zonder startkwalificatie om een opleiding te volgen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/14/257064/KNMB1_th04_p07_e001_q014.mp3', 1),
(116, 'Onderwijs en Opvoeding', 'Kun je in Nederland met een havo-diploma meteen naar de universiteit?', 'Ja dat kan.', 'Alleen als de docenten toestemming geven.', 'Nee dat kan niet.', 'C', 'Met een havo-diploma kun je naar het hbo (hogeschool), maar niet direct naar de universiteit. Daarvoor heb je een vwo-diploma nodig.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/15/257065/KNMB1_th04_p07_e001_q015.mp3', null),
(117, 'Onderwijs en Opvoeding', 'Mariam is klaar met de middelbare school. Ze wil een hbo-opleiding doen. Wat kan een reden zijn dat ze de opleiding niet mag volgen?', 'Ze heeft niet de goede vakken gedaan.', 'Ze heeft lage cijfers gehaald.', 'Ze is een vrouw.', 'A', 'Voor een hbo-opleiding is het juiste vooropleidingsniveau vereist, inclusief de juiste vakken (profieleis).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/16/257066/KNMB1_th04_p07_e001_q016.mp3', null),
(118, 'Onderwijs en Opvoeding', 'Sama zit in groep 8 van de basisschool. Volgend jaar gaat Sama naar het voortgezet onderwijs. Waar kan Sama naartoe gaan?', 'naar het vmbo', 'naar het mbo', 'naar het hbo', 'A', 'Na groep 8 van de basisschool gaan kinderen naar het voortgezet onderwijs: vmbo, havo of vwo.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/17/257067/KNMB1_th04_p07_e001_q017.mp3', 1),
(119, 'Onderwijs en Opvoeding', 'Marie krijgt haar eerste kind. Ze wil kinderbijslag aanvragen. Waar kan dat?', 'bij de Sociale Verzekeringsbank', 'bij DUO', 'bij Dienst Toeslagen', 'A', 'Kinderbijslag vraag je aan bij de Sociale Verzekeringsbank (SVB). Dit is een overheidsbijdrage voor de kosten van kinderen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/18/257068/KNMB1_th04_p07_e001_q018.mp3', null),
(120, 'Onderwijs en Opvoeding', 'Mert moet met de bus naar de middelbare school. Wie betaalt zijn reiskosten?', 'de ouders van Mert', 'de school van Mert', 'de overheid', 'C', 'De overheid vergoedt de reiskosten voor middelbare scholieren die verder dan een bepaalde afstand van school wonen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/19/257069/KNMB1_th04_p07_e001_q019.mp3', null),
(121, 'Onderwijs en Opvoeding', 'Aihan heeft een oudergesprek met de meester. De meester vertelt dat haar zoon niet aardig is tegen de andere kinderen. Aihan is blij dat de meester direct is. Waarom?', 'Ze kunnen nu goed met elkaar praten over het probleem.', 'Ze weet nu dat ze niets aan het probleem hoeft te doen.', 'Ze begrijpt nu dat ze niets aan het probleem kan doen.', 'A', 'Een open en direct gesprek over problemen met een kind zorgt voor een goede samenwerking tussen ouder en leraar.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/21/257070/KNMB1_th04_p07_e001_q021.mp3', null),
(122, 'Onderwijs en Opvoeding', 'Marieke is geslaagd voor de middelbare school. Ze hangt de vlag buiten. Hoe ziet de vlag eruit?', 'Vlag met oranje witte en blauwe strepen', 'Vlag met rode witte en blauwe strepen', 'Vlag met groene witte en rode strepen', 'B', 'Bij het slagen voor een examen wordt in Nederland de nationale vlag uitgehangen, eventueel met de schooltas eraan.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/22/257072/KNMB1_th04_p07_e001_q022.mp3', null),
(123, 'Onderwijs en Opvoeding', 'Welk Nederlandse feest is elk jaar op 5 december?', 'Sinterklaas', 'Eerste Kerstdag', 'Pasen', 'A', 'Sinterklaas is elk jaar op 5 december. Het is een typisch Nederlands kinderfeest waarbij Sint cadeautjes brengt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180844957/23/257073/KNMB1_th04_p07_e001_q023.mp3', null),
(124, 'Onderwijs en Opvoeding', 'Charlie is 12 jaar. Ze is in een telefoonwinkel en laat een telefoon vallen. De telefoon is kapot. Wie moet de telefoon betalen?', 'Charlie.', 'De ouders van Charlie.', 'De winkeleigenaar.', 'B', 'Voor schade veroorzaakt door een minderjarig kind zijn de ouders aansprakelijk, niet het kind zelf.', null, null),
(125, 'Onderwijs en Opvoeding', 'Kan je in Nederland met een vmbo-diploma meteen naar de universiteit?', 'Ja dat kan.', 'Alleen met toestemming van een docent.', 'Nee dat kan niet.', 'C', 'Met een vmbo-diploma ga je naar het mbo (middelbaar beroepsonderwijs). Direct naar de universiteit is niet mogelijk.', null, 1),
(126, 'Onderwijs en Opvoeding', 'Vanaf welke leeftijd moet een kind in Nederland verplicht naar school?', 'Vanaf 4 jaar.', 'Vanaf 5 jaar.', 'Vanaf 6 jaar.', 'B', 'De leerplicht in Nederland begint op 5-jarige leeftijd. Vanaf hun 5e verjaardag moeten kinderen verplicht naar school.', null, 1),
(127, 'Onderwijs en Opvoeding', 'Welke feestdag is elk jaar op 25 december?', 'Eerste Kerstdag.', 'Pasen.', 'Sinterklaas.', 'A', 'Eerste Kerstdag is altijd op 25 december. Nederland viert ook 26 december als Tweede Kerstdag.', null, null),
(128, 'Onderwijs en Opvoeding', 'Welk eten hoort bij Oud en Nieuw in Nederland?', 'Beschuit met muisjes.', 'Oliebollen.', 'Pepernoten.', 'B', 'Oliebollen zijn een typisch Nederlands oudjaarsgerecht. Ze worden gegeten rond Oud en Nieuw (31 december en 1 januari).', null, null),
(129, 'Werk en Inkomen', 'Aihan is kapper. Ze wil haar eigen bedrijf beginnen. Waar moet zij zich inschrijven?', 'bij het UWV', 'bij het uitzendbureau', 'bij de Kamer van Koophandel', 'C', 'Als je een eigen bedrijf start, moet je je inschrijven bij de Kamer van Koophandel (KvK). Dit is wettelijk verplicht.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/3/257030/KNMB1_th05_p09_e001_q003.mp3', null),
(130, 'Werk en Inkomen', 'Pedro woont in Nederland. Hij wil gaan werken. Wat moet Pedro eerst doen?', 'zich inschrijven bij het UWV', 'een cv maken', 'zich aanmelden voor werk', 'A', 'Als werkzoekende in Nederland schrijf je je in bij het UWV (Uitvoeringsinstituut Werknemersverzekeringen) voor begeleiding naar werk.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/4/257031/KNMB1_th05_p09_e001_q004.mp3', null),
(131, 'Werk en Inkomen', 'Jamal werkt als schoonmaker in een ziekenhuis. Hij werkt ''s nachts. Wat is voordeel van nachtwerk?', 'Het salaris is hoger.', 'Het werk is gemakkelijker.', 'Je hebt overdag vrij.', 'A', 'Nachtwerk is zwaarder dan dagwerk, daarom ontvangen werknemers een hogere vergoeding (toeslag) voor nachtdiensten.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/5/257032/KNMB1_th05_p09_e001_q005.mp3', null),
(132, 'Werk en Inkomen', 'Citra werkt in een winkel. Ze wil graag werken op maandagavond. Haar werkgever zegt dat het niet kan. Waarom niet?', 'Omdat ze niet voor het recht hebt.', 'Omdat maandagavond te laat is.', 'Omdat het in de cao staat dat ze niet mag werken op maandagavond.', 'C', 'De cao (collectieve arbeidsovereenkomst) bevat afspraken over arbeidsomstandigheden, werktijden en salaris die gelden voor een hele sector.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/6/257033/KNMB1_th05_p09_e001_q006.mp3', null),
(133, 'Werk en Inkomen', 'Marieke wil werken. Ze heeft een diploma, maar ze heeft geen werkervaring. Hoe kan ze haar kans op een baan groter maken?', 'als ze stage gaat lopen', 'als ze zich inschrijft bij de Kamer van Koophandel', 'als ze lid wordt van een vakbond', 'A', 'Stage loopt geeft je werkervaring op de arbeidsmarkt, wat je aantrekkelijker maakt voor werkgevers die werkervaring eisen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/8/257081/KNMB1_th05_p09_e001_q008.mp3', 1),
(134, 'Werk en Inkomen', 'Diego werkt in een winkel. Hij krijgt zijn jaaropgave. Wat staat er in een jaaropgave?', 'hoeveel werkervaring hij heeft', 'hoeveel salaris hij vorig jaar heeft gekregen', 'hoeveel huurtoeslag hij vorig jaar heeft gekregen', 'B', 'De jaaropgave is een overzicht van je totale salaris en inhoudingen over het afgelopen jaar. Dit heb je nodig voor je belastingaangifte.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/9/257082/KNMB1_th05_p09_e001_q009.mp3', null),
(135, 'Werk en Inkomen', 'Het nettosalaris van Feng is € 2000,-. Het brutosalaris van Feng is € 2500,-. Het verschil is € 500,-. Wat gebeurt er met deze € 500,-?', 'Het geld gaat naar Dienst Toeslagen.', 'Het geld gaat naar de Belastingdienst.', 'Het geld gaat naar de vakbond.', 'B', 'Het verschil tussen bruto- en nettosalaris (€500) gaat naar de Belastingdienst als loonbelasting en sociale premies.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/10/257083/KNMB1_th05_p09_e001_q010.mp3', 1),
(136, 'Werk en Inkomen', 'Lauren werkt in een ziekenhuis. Ze krijgt haar jaaropgave. Wat moet ze met haar jaaropgave doen?', 'minimaal vijf jaar bewaren', 'doorgeven aan DUO', 'opsturen naar de zorgverzekeraar', 'A', 'Je bent verplicht je jaaropgave minimaal vijf jaar te bewaren voor eventuele belastingcontroles.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/11/257084/KNMB1_th05_p09_e001_q011.mp3', null),
(137, 'Werk en Inkomen', 'Kumar solliciteert. Het bedrijf wil zijn cv zien. Wat is een cv?', 'een lijst van je persoonlijke gegevens, opleidingen en werkervaring', 'een sollicitatieformulier met je motivatie', 'een lijst van de arbeidsvoorwaarden', 'A', 'Een cv (curriculum vitae) is een overzicht van je persoonlijke gegevens, opleiding, werkervaring en vaardigheden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/12/257085/KNMB1_th05_p09_e001_q012.mp3', null),
(138, 'Werk en Inkomen', 'Samuel heeft een sollicitatiegesprek bij een kledingwinkel. Welke vraag kan hij krijgen?', 'Wat is je religie?', 'Heb je een grote familie?', 'Waarom wil je bij dit bedrijf komen werken?', 'C', 'Tijdens een sollicitatiegesprek wordt gevraagd naar je motivatie voor de functie en het bedrijf.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/13/257086/KNMB1_th05_p09_e001_q013.mp3', null),
(139, 'Werk en Inkomen', 'Mahmoud doet de Module Arbeidsmarkt en Participatie. Wat is dat?', 'een module die je voorbereidt op werken in Nederland', 'een module waarin je leert welke opleiding bij je past', 'een module waarin je leert over geld', 'A', 'De MAP (Module Arbeidsmarkt en Participatie) is een verplicht onderdeel van het inburgeringstraject dat je voorbereidt op de Nederlandse arbeidsmarkt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/14/257087/KNMB1_th05_p09_e001_q014.mp3', null),
(140, 'Werk en Inkomen', 'Nuria zoekt vacatures in de zorg. Waar kan ze vacatures vinden?', 'in een online vacaturebank', 'in de supermarkt', 'in de bibliotheek', 'A', 'Vacatures vind je via online vacaturebanken zoals Indeed, LinkedIn, Werk.nl of de website van het bedrijf zelf.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/15/257088/KNMB1_th05_p09_e001_q015.mp3', null),
(141, 'Werk en Inkomen', 'Mahmoud en zijn werkgever ondertekenen een arbeidsovereenkomst. Wat staat er in een arbeidsovereenkomst?', 'afspraken over het werk afspraken over de huur van zijn woning', 'afspraken over de kinderopvang', 'afspraken over het werk', 'C', 'Een arbeidsovereenkomst (arbeidscontract) bevat afspraken over functie, salaris, werktijden en overige arbeidsvoorwaarden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/16/257089/KNMB1_th05_p09_e001_q016.mp3', null),
(142, 'Werk en Inkomen', 'Mert wil in deeltijd werken. Kan dat in Nederland?', 'Alleen als dit in de cao staat.', 'Ja, dat kan.', 'Nee, dat kan niet.', 'B', 'Deeltijdwerk is volledig legaal in Nederland. Nederland heeft een van de hoogste percentages deeltijdwerkers ter wereld.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/17/257090/KNMB1_th05_p09_e001_q017.mp3', null),
(143, 'Werk en Inkomen', 'Sama werkt in een hotel. Ze heeft een vast contract. Wat is een vast contract?', 'een contract zonder einddatum', 'een contract met een einddatum', 'een contract via een uitzendbureau', 'A', 'Een vast contract (arbeidsovereenkomst voor onbepaalde tijd) heeft geen einddatum en geeft meer zekerheid dan een tijdelijk contract.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/18/257091/KNMB1_th05_p09_e001_q018.mp3', null),
(144, 'Werk en Inkomen', 'Nuria heeft een eigen bedrijf. Ze wil een verzekering afsluiten zodat ze toch een inkomen heeft als ze ziek wordt of niet kan werken. Welke verzekering kan ze afsluiten?', 'een arbeidsongeschiktheidsverzekering', 'een opstalverzekering', 'een wettelijke aansprakelijkheidsverzekering', 'A', 'Een arbeidsongeschiktheidsverzekering (AOV) biedt zzp''ers een inkomen als ze door ziekte of letsel niet kunnen werken.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/19/257092/KNMB1_th05_p09_e001_q019.mp3', null),
(145, 'Werk en Inkomen', 'Yana wil graag meedenken over belangrijke onderwerpen op het werk zoals de arbeidsvoorwaarden en de veiligheid. Van welke organisatie kan zij lid worden?', 'de ondernemingsraad', 'de personeelsvereniging', 'de woningcorporatie', 'A', 'De ondernemingsraad (OR) vertegenwoordigt werknemers en heeft inspraak bij besluiten over arbeidsomstandigheden en beleid.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/20/257093/KNMB1_th05_p09_e001_q020.mp3', null),
(146, 'Werk en Inkomen', 'Mariam werkt in een restaurant. Ze wil graag een hoger salaris. Wat kan ze doen?', 'Ze kan een gesprek met haar werkgever aanvragen.', 'Ze kan de vakbond om een hoger salaris vragen.', 'Niets, want ze heeft een arbeidsovereenkomst getekend.', 'A', 'Je kunt altijd een gesprek aanvragen met je werkgever over je salaris. Onderbouw je verzoek met prestaties en marktwaarde.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/22/257095/KNMB1_th05_p09_e001_q022.mp3', null),
(147, 'Werk en Inkomen', 'Mert werkt bij een bouwbedrijf. Hij heeft een beoordelingsgesprek met zijn werkgever. Over welke onderwerpen gaat het gesprek?', 'over de verzekeringen van Mert', 'over de sollicitatiebrief van Mert', 'over hoe Mert functioneert', 'C', 'Een beoordelingsgesprek (functioneringsgesprek) gaat over hoe je functioneert in je functie en je ontwikkelpunten.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180849348/23/257096/KNMB1_th05_p09_e001_q023.mp3', null),
(148, 'Werk en Inkomen', 'Jason werkt in de zorg. Zijn brutosalaris van september is €2.900. Wat krijgt hij op zijn bankrekening?', 'Minder dan €2.900', 'Precies €2.900', 'Meer dan €2.900', 'A', 'Van je brutosalaris worden loonbelasting en sociale premies afgehouden. Wat overblijft is je nettosalaris.', null, null),
(149, 'Werk en Inkomen', 'Wat moet je vaak naar een bedrijf sturen als je solliciteert?', 'Een sollicitatiebrief en een kopie van je zorgpas', 'Een sollicitatiebrief en een bankpas', 'Een sollicitatiebrief en een cv', 'C', 'Bij een sollicitatie stuur je een motivatiebrief en een cv mee. Dit zijn de standaard documenten bij een sollicitatie.', null, null),
(150, 'Werk en Inkomen', 'Maartje krijgt kinderopvangtoeslag. Ze krijgt een nieuwe baan en gaat meer geld verdienen. Wat gebeurt er waarschijnlijk met haar kinderopvangtoeslag?', 'Haar kinderopvangtoeslag gaat omlaag', 'Haar kinderopvangtoeslag blijft gelijk', 'Haar kinderopvangtoeslag gaat omhoog', 'A', 'Kinderopvangtoeslag is inkomensgerelateerd. Bij een hoger inkomen ontvang je minder toeslag.', null, null),
(151, 'Werk en Inkomen', 'Mark werkt in een supermarkt. Zijn contract eindigt op 31 mei. Hij heeft nog geen ander werk gevonden. Wanneer kan Mark een uitkering aanvragen?', 'Vanaf 24 mei', 'Vanaf 30 juni', 'Hij hoeft zelf geen uitkering aan te vragen. Het gaat automatisch', 'B', 'De WW (werkloosheiduitkering) kun je aanvragen als je werkloos bent. De uitkering gaat in nadat je werkloosheidsperiode is begonnen.', null, null),
(152, 'Werk en Inkomen', 'Eva wil graag een deeltijdbaan. Kan dat in Nederland?', 'Ja dat kan', 'Alleen als ze ook een opleiding volgt', 'Nee dat kan niet', 'A', 'Deeltijdwerk is volledig toegestaan in Nederland. Je hebt het recht te vragen om deeltijdwerk.', null, null),
(153, 'Werk en Inkomen', 'Ming wil een eigen schoenenwinkel beginnen. Wat moet zij doen, volgens de wet?', 'Ze moet lid worden van een vakbond', 'Ze moet veel reclame maken voor haar bedrijf', 'Ze moet zich inschrijven bij de Kamer van Koophandel', 'C', 'Wie een eigen bedrijf start is verplicht zich in te schrijven bij de Kamer van Koophandel (KvK). Dit is wettelijk verplicht.', null, null),
(154, 'Werk en Inkomen', 'Mag een werkgever eisen dat je goed Nederlands kunt schrijven?', 'Ja, dat mag altijd', 'Alleen als het nodig is voor de baan', 'Nee dat mag nooit', 'B', 'Een werkgever mag eisen dat je een bepaald taalniveau hebt, maar alleen als dat noodzakelijk is voor de functie.', null, null),
(155, 'Werk en Inkomen', 'Lotte is automonteur.  Ze heeft een contract zonder einddatum. Hoe noem je het contract van Lotte?', 'Een nul-uren contract', 'Een tijdelijk contract', 'Een vast contract', 'C', 'Een contract zonder einddatum is een vast contract. Het geeft de werknemer meer baanzekerheid.', null, 1),
(156, 'Werk en Inkomen', 'Abdel krijgt een vast contract bij een bedrijf. Moet hij zich inschrijven bij de Kamer van Koophandel (KvK)?', 'Ja, dat moet volgens de wet.', 'Alleen als hij vijf dagen per week werkt.', 'Nee, dat moeten alleen mensen met een eigen bedrijf.', 'C', 'Alleen zelfstandigen (zzp''ers en ondernemers) hoeven zich in te schrijven bij de KvK. Werknemers in loondienst niet.', null, null),
(157, 'Werk en Inkomen', 'Werkgevers maken afspraken met nieuwe werknemers. Welke afspraken maken zij vaak?', 'Afspraken over hobby''s en reiskosten.', 'Afspraken over hobby''s en werktijden.', 'Afspraken over reiskosten en werktijden.', 'C', 'Bij een nieuw contract worden arbeidsvoorwaarden zoals reiskosten, werktijden, salaris en vakantiedagen afgesproken.', null, null),
(158, 'Werk en Inkomen', 'Maria krijgt een uitkering. Ze zoekt al lange tijd naar werk. Nadja wil een cursus doen om snel werk te vinden. Wie kan haar hiermee helpen?', 'De Belastingdienst.', 'Haar bank.', 'Het UWV.', 'C', 'Het UWV (Uitvoeringsinstituut Werknemersverzekeringen) helpt werklozen met re-integratie, cursussen en uitkeringen.', null, null),
(159, 'Werk en Inkomen', 'David heeft een diploma uit Amerika. Hij wil zijn Amerikaanse diploma laten waarderen in Nederland. Waar kan dit?', 'Bij de bibliotheek.', 'Bij de IDW.', 'Bij een universiteit.', 'B', 'Buitenlandse diploma''s worden beoordeeld door IDW (Internationale Diplomawaardering), onderdeel van DUO.', null, 1),
(160, 'Werk en Inkomen', 'Sander werkt bij een bedrijf. Hij schrijft elke dag op hoeveel uur hij heeft gewerkt. Dat moet van het bedrijf. Mag het bedrijf dat eisen?', 'Ja, dat mag.', 'Alleen als Abdel in deeltijd werkt.', 'Nee, want dat is persoonlijke informatie.', 'A', 'Een werkgever mag bijhouden hoeveel uren werknemers werken. Dit is toegestaan en gebruikelijk voor salarisadministratie.', null, null),
(161, 'Werk en Inkomen', 'Mira heeft een eigen bedrijf. Ze heeft een arbeidsongeslachtsheidsverzekering (AOV). Wanneer krijgt Tami geld van deze verzekering?', 'Als er iets kapotgaat in haar bedrijf.', 'Als ze langere tijd ziek is.', 'Als ze vrije dagen wil.', 'B', 'Een AOV (arbeidsongeschiktheidsverzekering) keert uit als je door langdurige ziekte of een ongeluk niet kunt werken.', null, 1),
(162, 'Werk en Inkomen', 'Lotte werkt als schoonmaakster. Ze heeft een tijdelijk contract. Wat is dat?', 'Een contract met een einddatum.', 'Een contract voor deeltijdwerk.', 'Een contract zonder vaste werkdagen.', 'A', 'Een tijdelijk contract heeft een vaste einddatum. Na afloop loopt het contract automatisch af.', null, null),
(163, 'Werk en Inkomen', 'Wat doet de personeelsvereniging van een bedrijf?', 'Activiteiten organiseren voor werknemers.', 'Nieuwe werknemers aannemen.', 'Regels maken over werk en werktijden.', 'A', 'De personeelsvereniging organiseert activiteiten voor werknemers, zoals uitjes, sportactiviteiten en feesten.', null, 1),
(164, 'Werk en Inkomen', 'Nordin is aan het inburgeren. Hij bereidt zich voor op werk. Wat is verplicht?', 'De Module Arbeidsmarkt en Participatie (MAP).', 'Een cursus solliciteren.', 'Inschrijven bij een uitzendbureau.', 'A', 'De MAP (Module Arbeidsmarkt en Participatie) is verplicht voor alle inburgeraars en bereidt voor op de Nederlandse arbeidsmarkt.', null, null),
(165, 'Werk en Inkomen', 'Jason werkt in de zorg. Zijn brutosalaris van september is €2.900. Wat krijgt hij op zijn bankrekening?', 'Minder dan € 2.900.', 'Precies € 2.900.', 'Meer dan € 2.900.', 'A', 'Van je brutosalaris worden belastingen en premies afgehouden. Je nettosalaris is altijd lager dan je brutosalaris.', null, null),
(166, 'Werk en Inkomen', 'Wat moet je vaak naar een bedrijf sturen als je solliciteert?', 'Een sollicitatiebrief en een kopie van je zorgpas.', 'Een sollicitatiebrief en je cv (curriculum vitae).', 'Je cv (curriculum vitae) en een kopie van je zorgpas.', 'B', 'Bij een sollicitatie stuur je standaard een motivatiebrief (sollicitatiebrief) en een cv mee.', null, null),
(167, 'Werk en Inkomen', 'Maartje krijgt kinderopvangtoeslag. Ze krijgt een nieuwe baan en gaat meer geld verdienen. Wat gebeurt waarschijnlijk?', 'Haar kinderopvangtoeslag gaat omhoog.', 'Haar kinderopvangtoeslag blijft gelijk.', 'Haar kinderopvangtoeslag gaat omlaag.', 'C', 'Kinderopvangtoeslag is inkomensafhankelijk: bij hogere inkomsten neemt de toeslag af.', null, null),
(168, 'Werk en Inkomen', 'Mark werkt in een supermarkt. Zijn contract eindigt op 31 mei. Hij heeft nog geen ander werk gevonden. Wanneer kan hij een werkloosheidsuitkering (WW) aanvragen?', 'Vanaf 24 mei.', 'Vanaf 30 juni.', 'Hij hoeft zelf geen uitkering aan te vragen dat gaat automatisch.', 'B', 'De WW-uitkering kun je aanvragen als je werkloos bent. De uitkering gaat in op de eerste werkloosheidsdag na het contract.', null, 1),
(169, 'Werk en Inkomen', 'Eva wil graag een deeltijdbaan. Kan dat in Nederland?', 'Ja dat kan.', 'Alleen als ze ook een opleiding volgt.', 'Nee dat kan niet.', 'A', 'In Nederland werk je zo vaak je wilt en kunt. Deeltijdwerk is volledig toegestaan en gangbaar.', null, null),
(170, 'Werk en Inkomen', 'Ming wil een eigen schoenenwinkel beginnen. Wat moet zij doen volgens de wet?', 'Ze moet lid worden van een vakbond.', 'Ze moet veel reclame maken voor haar bedrijf.', 'Ze moet zich inschrijven bij de Kamer van Koophandel.', 'C', 'Het inschrijven bij de KvK is verplicht voor iedereen die een eigen bedrijf start in Nederland.', null, null),
(171, 'Werk en Inkomen', 'Mag een werkgever eisen dat je goed Nederlands kunt schrijven?', 'Ja dat mag altijd.', 'Alleen als het nodig is voor de baan.', 'Nee dat mag nooit.', 'B', 'Taalvereisten op het werk zijn toegestaan als de functie dat vraagt. Discriminatie is niet toegestaan.', null, null),
(172, 'Werk en Inkomen', 'Lotte is automonteur. Ze heeft een contract zonder einddatum. Hoe noem je het contract van Lotte?', 'Een nul-urencontract.', 'Een tijdelijk contract.', 'Een vast contract.', 'C', 'Een vast contract (voor onbepaalde tijd) geeft meer zekerheid dan een tijdelijk contract.', null, null),
(173, 'Instanties', 'Bartek is 14 jaar. Het stoplicht is rood, maar hij rijdt door. De politie wil het identiteitsbewijs van Bartek zien. Moet hij zijn identiteitsbewijs aan de politie geven?', 'Ja dat moet.', 'Alleen als zijn ouders toestemming geven.', 'Nee dat hoeft niet.', 'A', 'In Nederland ben je vanaf 14 jaar verplicht een identiteitsbewijs bij je te dragen. Je moet het tonen als de politie erom vraagt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/3/257099/KNMB1_th06_p05_e001_q003.mp3', null),
(174, 'Instanties', 'De moeder van Nuria is overleden. Moet Nuria dit aan de gemeente doorgeven?', 'Alleen als de moeder van Nuria jonger dan 70 jaar was.', 'Ja dat is verplicht.', 'Nee dat hoeft niet.', 'B', 'Overlijden is een wijziging in de burgerlijke stand die je verplicht bij de gemeente moet doorgeven.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/4/257100/KNMB1_th06_p05_e001_q004.mp3', null),
(175, 'Instanties', 'De vriendin van Feng heeft een baby gekregen. Feng wil de vader van het kind zijn. Waar kan hij het kind erkennen?', 'bij de gemeente', 'bij het ziekenhuis', 'bij de gynaecologh', 'A', 'Een kind erkennen doe je bij de gemeente. De erkenning legt de juridische band tussen vader en kind vast.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/5/257101/KNMB1_th06_p05_e001_q005.mp3', 1),
(176, 'Instanties', 'Kumar woont twee jaar in Nederland. Hij wil de Nederlandse nationaliteit aanvragen. Kan dit?', 'Ja dat kan.', 'Alleen als Kumar in Nederland werkt.', 'Nee dat kan niet.', 'A', 'De Nederlandse nationaliteit aanvragen (naturalisatie) kan na minimaal vijf jaar legaal verblijf in Nederland, niet na twee jaar.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/6/257102/KNMB1_th06_p05_e001_q006.mp3', null),
(177, 'Instanties', 'Lauren komt uit Amerika. Ze wil graag in Nederland wonen. Waar kan ze een verblijfsvergunning aanvragen?', 'bij DUO', 'bij de gemeente', 'bij de IND', 'C', 'Een verblijfsvergunning voor niet-EU-burgers wordt aangevraagd bij de IND (Immigratie- en Naturalisatiedienst).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/7/257103/KNMB1_th06_p05_e001_q007.mp3', null),
(178, 'Instanties', 'Toby en Yana gaan samenwonen. Waar moeten ze dit doorgeven?', 'bij de gemeente', 'bij de Kamer van Koophandel', 'bij de Nationale ombudsman', 'A', 'Samenwonen moet je melden bij de gemeente door je in te schrijven in de BRP (Basisregistratie Personen).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/8/257104/KNMB1_th06_p05_e001_q008.mp3', null),
(179, 'Instanties', 'Wie moeten riool- en afvalstoffenheffing betalen aan de gemeente?', 'alle mensen die in de gemeente wonen', 'alle bedrijven in een gemeente', 'alle mensen die bij de gemeente werken', 'A', 'Riool- en afvalstoffenheffing is een gemeentelijke belasting die alle inwoners van de gemeente moeten betalen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/9/257105/KNMB1_th06_p05_e001_q009.mp3', null),
(180, 'Instanties', 'Diego krijgt een e-mail: U heeft een auto gewonnen! Als u uw inloggegevens van uw DigiD opstuurt dan krijgt u snel de auto. Moet Diego zijn inloggegevens opsturen?', 'Ja dat moet.', 'Alleen als het een Nederlands bedrijf is.', 'Nee dat moet hij nooit doen.', 'C', 'Je DigiD-inloggegevens zijn strikt persoonlijk. De overheid of een bedrijf vraagt nooit om je DigiD-gegevens via e-mail.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/10/257106/KNMB1_th06_p05_e001_q010.mp3', null),
(181, 'Instanties', 'Hoe weet je hoeveel belasting je moet betalen?', 'door belastingaangifte te doen', 'door de belastingdienst te bellen', 'door het aan je werkgever te vragen', 'A', 'Via belastingaangifte geef je op hoeveel je hebt verdiend. De Belastingdienst berekent dan hoeveel belasting je moet betalen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/11/257107/KNMB1_th06_p05_e001_q011.mp3', null),
(182, 'Instanties', 'Waarvoor gebruikt de overheid het belastinggeld?', 'voor goede wegen', 'voor goede kinderopvang', 'voor goedkope boodschappen', 'A', 'Belastinggeld financiert publieke voorzieningen zoals wegen, ziekenhuizen, onderwijs en uitkeringen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/12/257108/KNMB1_th06_p05_e001_q012.mp3', null),
(183, 'Instanties', 'Toby doet belastingaangifte maar hij begrijpt het niet. Waar kan Toby hulp krijgen?', 'bij de Belastingdienst en de bibliotheek', 'bij de bibliotheek en de IND', 'bij de Belastingdienst en de IND', 'C', 'De Belastingdienst en de Belastingtelefoon kunnen helpen bij vragen over belastingaangifte. De IND gaat over verblijfsvergunningen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/13/257109/KNMB1_th06_p05_e001_q013.mp3', null),
(184, 'Instanties', 'Luc loopt op straat. Hij ziet een ongeluk. Een vrouw ligt op straat met veel bloed. Wat kan Luc doen?', 'Hij kan 112 bellen voor een ambulance.', 'Hij kan 0900-8844 bellen voor de politie.', 'Hij kan zijn huisarts bellen.', 'A', 'Bij een ongeluk met gewonden bel je altijd 112 voor politie, brandweer of ambulance.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/14/257110/KNMB1_th06_p05_e001_q014.mp3', null),
(185, 'Instanties', 'Wat is geen taak van de politie?', 'afval opruimen', 'boetes uitdelen', 'op drukke plekken kijken of het goed gaat', 'A', 'De politie handhaaft de wet, lost misdaden op en zorgt voor openbare orde. Afval ophalen is een gemeentelijke taak.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/15/257111/KNMB1_th06_p05_e001_q015.mp3', null),
(186, 'Instanties', 'Zeynep heeft op haar werk last van discriminatie. Ze wil dat het stopt. Wie kan ze om hulp vragen?', 'de politie', 'het UWV', 'de Kamer van Koophandel', 'A', 'Bij discriminatie op het werk kun je terecht bij de politie of het College voor de Rechten van de Mens.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/16/257112/KNMB1_th06_p05_e001_q016.mp3', null),
(187, 'Instanties', 'Mariam is eenzaam. Ze wil graag hulp. Waar kan ze hulp vragen?', 'bij de schuldhulpverlening', 'bij maatschappelijk werk', 'bij het Nibud', 'B', 'Maatschappelijk werk biedt begeleiding en ondersteuning bij persoonlijke, sociale of praktische problemen zoals eenzaamheid.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/17/257113/KNMB1_th06_p05_e001_q017.mp3', 1),
(188, 'Instanties', 'Marie heeft een brief gekregen van de Belastingdienst maar ze vindt dat de informatie in de brief niet goed is. Wat kan Marie doen?', 'hulp vragen bij de Nationale ombudsman', 'bezwaar maken bij de Belastingdienst', 'de politie bellen', 'B', 'Als je het niet eens bent met een beslissing van de Belastingdienst, kun je een bezwaarschrift indienen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/18/257114/KNMB1_th06_p05_e001_q018.mp3', 1),
(189, 'Instanties', 'Mert is getrouwd maar hij wil scheiden. Hij weet niet hoe dit moet. Waar kan Mert advies vragen?', 'bij het Juridisch Loket', 'bij de Nationale ombudsman', 'bij de schuldhulpverlening', 'A', 'Het Juridisch Loket biedt gratis juridisch advies voor mensen met juridische vragen, zoals bij een scheiding.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/19/257115/KNMB1_th06_p05_e001_q019.mp3', null),
(190, 'Instanties', 'De buren van Marieke maken veel geluid. Ze heeft al een aantal keer met de buren gepraat maar ze maken nog steeds veel geluid. Marieke wil dat het stopt. Wat kan ze doen?', 'de politie bellen', 'het Juridisch Loket om advies vragen', 'hulp vragen bij de Nationale ombudsman', 'B', 'Het Juridisch Loket geeft gratis juridisch advies. Bij aanhoudende overlast van buren kunnen zij de juiste stappen uitleggen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/21/257117/KNMB1_th06_p05_e001_q021.mp3', 1),
(191, 'Instanties', 'Lars pakt iets uit een winkel zonder te betalen en rent weg. De politie ziet het en zegt: Stop! Moet Lars stoppen?', 'Ja dat moet.', 'Alleen als hij iets duurs heeft gestolen.', 'Nee dat hoeft niet.', 'A', 'In Nederland moet je altijd stoppen als de politie je aanhoudt. Wegrijden of niet stoppen is strafbaar.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/22/257118/KNMB1_th06_p05_e001_q022.mp3', null),
(192, 'Instanties', 'Sama heeft weinig geld. Ze wil graag eten halen bij de voedselbank. Waar kan ze vragen of ze hier recht op heeft?', 'bij het UWV', 'bij de schuldhulpverlening', 'bij de voedselbank', 'C', 'Voor de voedselbank moet je je aanmelden via een hulpverlener of rechtstreeks bij de voedselbank zelf.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180875101/23/257119/KNMB1_th06_p05_e001_q023.mp3', null),
(193, 'Instanties', 'Tim en Max zijn twee mannen. Ze willen met elkaar trouwen. Wat staat hierover in de Nederlandse wet?', 'Dat mag.', 'Dat beslist de gemeente.', 'Dat mag niet.', 'A', 'In Nederland is het huwelijk voor iedereen wettelijk toegestaan, ongeacht geslacht. Het homohuwelijk is legaal.', null, null),
(194, 'Instanties', 'Romy zoekt informatie over de kinderopvangtoeslag. Naar welke website kan zij het beste gaan?', 'www.belastingdienst.nl', 'www.kvk.nl', 'www.uwv.nl', 'A', 'Informatie over kinderopvangtoeslag vind je op de officiële website van de Belastingdienst (belastingdienst.nl).', null, null),
(195, 'Instanties', 'Amber en Nick gaan samenwonen. Moeten ze dit melden aan de gemeente?', 'Ja, dat is verplicht.', 'Alleen als ze gaan trouwen.', 'Nee, dat gebeurt automatisch.', 'A', 'Samenwonen moet je doorgeven bij de gemeente door je in te schrijven in de Basisregistratie Personen (BRP).', null, null),
(196, 'Instanties', 'Youssef wil een Nederlands paspoort aanvragen. Waar kan hij dat doen?', 'Bij de Belastingdienst.', 'Bij de gemeente.', 'Bij het postkantoor.', 'B', 'Een Nederlands paspoort of identiteitskaart vraag je aan bij je gemeente.', null, null),
(197, 'Instanties', 'Bram wil inloggen op de website van het UWV. Wat heeft hij nodig?', 'Zijn BSN-nummer.', 'Zijn DigiD.', 'Zijn postcode en huisnummer.', 'B', 'Voor toegang tot overheidsdiensten zoals het UWV gebruik je DigiD, jouw digitale identiteit voor de overheid.', null, null),
(198, 'Instanties', 'Waar kun je in Nederland huurtoeslaag aanvragen?', 'Bij de Belastingdienst.', 'Bij de gemeente.', 'Bij de woningbouwvereniging.', 'A', 'Huurtoeslag vraag je aan bij de Belastingdienst (Dienst Toeslagen). Niet bij de gemeente of woningcorporatie.', null, null),
(199, 'Instanties', 'Layla heeft een uitkering. Ze gaat samenwonen met haar vriend. Verandert haar uitkering?', 'Ja, haar uitkering gaat omhoog.', 'Haar uitkering verandert misschien.', 'Nee, haar uitkering blijft zeker hetzelfde.', 'B', 'Als je samenwoont, kan dit gevolgen hebben voor je uitkering omdat het inkomen van je partner meetelt bij de berekening.', null, 1),
(200, 'Instanties', 'Waarbij helpt het Juridisch Loket?', 'Bij het leren van Nederlands.', 'Bij het zoeken naar een woning.', 'Bij vragen over rechten en plichten.', 'C', 'Het Juridisch Loket helpt met vragen over rechten en plichten, arbeidsrecht, huurrecht en andere juridische zaken.', null, null),
(201, 'Instanties', 'Wat kun je met een DigiD?', 'Geld overmaken naar het buitenland.', 'Solliciteren voor een baan in Nederland.', 'Veilig inloggen op websites van de overheid.', 'C', 'Met DigiD log je veilig in op websites van de overheid, zoals belastingdienst.nl, mijnoverheid.nl en uwv.nl.', null, null),
(202, 'Instanties', 'Latisha en Koen zijn vorige maand gescheiden. Waar zij dit doorgeven?', 'Bij de gemeente.', 'Bij de Kamer van Koophandel.', 'Bij het NIBUD.', 'A', 'Een scheiding moet je registreren bij de gemeente, zodat de burgerlijke stand wordt bijgewerkt.', null, null),
(203, 'Instanties', 'In Nederland betalen mensen belasting. Dit geld wordt voor veel dingen gebruikt. Wat wordt betaald maar niet van belastingsgeld?', 'De salarissen van bankmedewerkers.', 'Het maken van dijken.', 'WW-uitkeringen.', 'A', 'Belastinggeld betaalt voor publieke diensten. Salarissen van bankmedewerkers worden betaald door de bank zelf.', null, null),
(204, 'Instanties', 'Luuk is 15 jaar en heeft iets gestolen. De politie vraagt om Luuks identiteitsbewijs. Moet Luuk dat geven?', 'Ja dat moet hij.', 'Alleen als hij iets duurs gestolen heeft.', 'Nee want hij is nog geen 18 jaar.', 'A', 'Iedereen van 14 jaar en ouder moet zich kunnen identificeren aan de politie. Weigeren is strafbaar.', null, null),
(205, 'Instanties', 'In Nederland kunnen ouders kinderbijslag krijgen. Waar kun je kinderbijslag aanvragen?', 'Bij de Sociale Verzekeringsbank (SVB).', 'Bij DUO.', 'Bij een zorgverzekering.', 'A', 'Kinderbijslag vraag je aan bij de SVB (Sociale Verzekeringsbank), niet bij de gemeente of Belastingdienst.', null, 1),
(206, 'Instanties', 'Erik is geslaagd voor zijn rijexamen. Waar kan Erik een rijbewijs aanvragen?', 'Bij de Belastingdienst.', 'Bij de gemeente.', 'Bij de rijschool.', 'B', 'Een rijbewijs vraag je aan bij de gemeente, nadat je geslaagd bent voor het CBR-rijexamen.', null, null),
(207, 'Instanties', 'Is belastingaangifte doen verplicht in Nederland?', 'Ja dat is vaak verplicht.', 'Alleen voor bedrijven.', 'Nee dat is nooit verplicht.', 'A', 'Belastingaangifte doen is verplicht voor mensen die een aangifte ontvangen van de Belastingdienst.', null, null),
(208, 'Staatsinrichting en Rechtsstaat', 'Aihan is lid van een politieke partij. Mensen kunnen op haar stemmen tijdens de verkiezingen. Welk kiesrecht gebruikt Aihan?', 'actief kiesrecht', 'passief kiesrecht', 'beslissend kiesrecht', 'B', 'Passief kiesrecht is het recht om jezelf verkiesbaar te stellen. Actief kiesrecht is het recht om te stemmen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/3/257122/Shutterstock_2127014192_v.png', 1),
(209, 'Staatsinrichting en Rechtsstaat', 'Er zijn verkiezingen in Nederland. Waar kun je op stemmen?', 'Je kunt stemmen wie de nieuwe koning wordt.', 'Je kunt stemmen op twee politieke partijen.', 'Je kunt stemmen op leden van veel verschillende politieke partijen.', 'C', 'Bij Nederlandse verkiezingen stem je op een politieke partij of een kandidaat van een partij. Je kunt niet op de koning stemmen.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/4/257123/Shutterstock_2433845729_v.png', null),
(210, 'Staatsinrichting en Rechtsstaat', 'Wat is niet nodig om te stemmen?', 'Je bent 18 jaar of ouder.', 'Je hebt de Nederlandse nationaliteit.', 'Je hebt een opleiding gedaan.', 'C', 'Om te mogen stemmen heb je de Nederlandse nationaliteit en een leeftijd van 18 jaar nodig. Een diploma is niet vereist.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/5/257124/Shutterstock_2122158887_v.png', null),
(211, 'Staatsinrichting en Rechtsstaat', 'Er is in Nederland machtenscheiding. Waarom is machtenscheiding belangrijk?', 'De kans op corruptie bij de overheid is dan kleiner.', 'Eén persoon of één groep kan dan snel dingen beslissen.', 'De overheid en de politie hoeven zich dan niet aan de wetten te houden.', 'A', 'Machtenscheiding voorkomt dat één persoon of groep te veel macht krijgt. Dit vermindert de kans op corruptie en machtsmisbruik.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/6/257125/shutterstock_2482440449_v.png', 1),
(212, 'Staatsinrichting en Rechtsstaat', 'Moet de Nederlandse overheid zich aan de wet houden?', 'Ja, dat moet.', 'Alleen als er in de wet staat dat de wet ook voor de overheid is.', 'Nee, dat hoeft niet.', 'A', 'In een rechtsstaat gelden de wetten voor iedereen, ook voor de overheid. Dit is een fundamenteel principe van de democratie.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/7/257126/Shutterstock_2463843837_v.png', null),
(213, 'Staatsinrichting en Rechtsstaat', 'Samuel heeft iets meegenomen uit een winkel zonder te betalen. Hij moet naar de rechter en krijgt straf. Hij vindt dat hij te veel straf krijgt. Wat kan hij doen?', 'niets', 'in hoger beroep gaan', 'de politie bellen', 'B', 'Als je het niet eens bent met een rechterlijke uitspraak, kun je in hoger beroep gaan bij een hogere rechtbank.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/8/257127/Shutterstock_2064689006_v.png', null),
(214, 'Staatsinrichting en Rechtsstaat', 'Welke drie machten zijn er in Nederland?', 'de denkende macht, de makende macht en de luisterende macht', 'de kiezende macht, de toezichthoudende macht en de controlerende macht', 'de wetgevende macht, de uitvoerende macht en de rechterlijke macht', 'C', 'De drie machten in Nederland zijn: de wetgevende macht (parlement), de uitvoerende macht (regering) en de rechterlijke macht (rechtbanken).', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/9/257128/Shutterstock_2386517631_v.png', null),
(215, 'Staatsinrichting en Rechtsstaat', 'Welke twee taken heeft de regering?', 'wetten maken en wetten uitvoeren', 'de Troonrede voorlezen en met Kerst het land toespreken', 'wetten ondertekenen en andere landen bezoeken', 'A', 'De regering maakt wetten samen met het parlement en zorgt voor de uitvoering van die wetten.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/10/257129/bordes_v.png', null),
(216, 'Staatsinrichting en Rechtsstaat', 'Hoe heet de koning van Nederland?', 'Willem van Oranje', 'Willem-Alexander', 'Máxima', 'B', 'De koning van Nederland is Willem-Alexander, die in 2013 koningin Beatrix opvolgde.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/11/257130/Shutterstock_2509330805_v.png', null),
(217, 'Staatsinrichting en Rechtsstaat', 'Mahmoud is gekozen als minister. Waar werkt hij?', 'in de gemeenteraad', 'in de regering', 'in de Eerste Kamer', 'B', 'Ministers werken in de regering (het kabinet). De minister-president leidt de ministerraad.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/12/257131/Shutterstock_574829092_v.png', 1),
(218, 'Staatsinrichting en Rechtsstaat', 'Wat bestuurt de Nederlandse regering?', 'Europa, het land en de provincies', 'het land, de waterschappen en de gemeenten', 'het land, de provincies en de gemeenten', 'C', 'De Nederlandse regering bestuurt het land op nationaal niveau; provincies en gemeenten besturen hun eigen gebieden.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/13/257132/Shutterstock_1901720521_v.png', null),
(219, 'Staatsinrichting en Rechtsstaat', 'Lauren woont in Nederland. Ze heeft geen religie. Mag dit in Nederland?', 'Ja, dat mag.', 'Alleen als ze toestemming van de overheid heeft.', 'Nee, in Nederland moet je een religie hebben.', 'A', 'In Nederland is vrijheid van godsdienst grondwettelijk vastgelegd. Je mag geloven of niet geloven wat je wilt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/14/257133/Shutterstock_2060179340_v.png', null),
(220, 'Staatsinrichting en Rechtsstaat', 'Marie is boos op de overheid. Ze zet een bericht op internet. In het bericht vraagt ze mensen om te demonstreren en om geweld te gebruiken. Mag dit in Nederland?', 'Ja, dat mag.', 'Alleen als ze tegen de overheid zegt dat ze gaat demonstreren.', 'Nee, dat mag niet.', 'C', 'In Nederland is er vrijheid van meningsuiting, maar het oproepen tot geweld is strafbaar onder het Wetboek van Strafrecht.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/15/257134/Shutterstock_1823288369_v.png', null),
(221, 'Staatsinrichting en Rechtsstaat', 'Mert is in de supermarkt. Een medewerker van de supermarkt wil zijn BSN weten. Moet Mert zijn BSN aan de supermarkt geven?', 'Ja, dat moet.', 'Alleen als de supermarkt zijn BSN nodig heeft.', 'Nee, dat hoeft niet.', 'C', 'Je BSN (burgerservicenummer) is privéinformatie. Alleen instanties die dit wettelijk mogen vragen (zoals de overheid) hebben er recht op.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/16/257135/Shutterstock_1906390078_v.png', null),
(222, 'Staatsinrichting en Rechtsstaat', 'Sama is zwanger en krijgt een kind. Ze wil graag werken als het kind is geboren. Mag dit in Nederland?', 'Ja, dat mag.', 'Dat mag als Sama alleen woont.', 'Nee, dat mag niet.', 'A', 'In Nederland hebben vrouwen en mannen gelijke rechten, inclusief het recht om te werken na de bevalling.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/17/257136/Shutterstock_2259579987_v.png', null),
(223, 'Staatsinrichting en Rechtsstaat', 'Wat is strafbaar in Nederland?', 'euthanasie', 'eerwraak', 'abortus', 'B', 'Eerwraak is een misdrijf in Nederland en wordt strafrechtelijk vervolgd. Geweld is altijd strafbaar, ook binnen families.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/18/257137/Shutterstock_2186271797_v.png', 1),
(224, 'Staatsinrichting en Rechtsstaat', 'Wat is zelfbeschikkingsrecht?', 'Je mag zelf kiezen hoe je wilt leven.', 'Je mag zelf wetten en regels maken.', 'Je mag zelf kiezen aan welke wetten je je houdt.', 'A', 'Zelfbeschikkingsrecht betekent dat iedereen het recht heeft zelf te bepalen hoe hij of zij wil leven, zolang dit binnen de wet valt.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/19/257138/Shutterstock_2464288371_v%20%281%29.png', 1),
(225, 'Staatsinrichting en Rechtsstaat', 'Waar heb je in Nederland volgens de wet geen recht op?', 'ongewenste intimiteit', 'privacy', 'gelijke behandeling', 'A', 'In Nederland heb je recht op gelijke behandeling, vrijheid en veiligheid. Ongewenste intimiteit is niet toegestaan en strafbaar.', 'https://leren.kleurrijker.nl/pluginfile.php/424563/question/questiontext/180989903/20/257139/Shutterstock_2483357455_v.png', 1),
(226, 'Staatsinrichting en Rechtsstaat', 'Sam mag stemmen. Hij heeft kiesrecht. Hoe heet dit kiesrecht?', 'Actief kiesrecht.', 'Passief kiesrecht.', 'Verplicht kiesrecht.', 'A', 'Actief kiesrecht is het recht om te stemmen. Passief kiesrecht is het recht om je verkiesbaar te stellen.', null, null),
(227, 'Staatsinrichting en Rechtsstaat', 'Chris heeft een Nederlands paspoort. Voor zijn werk moet hij naar België een land in de EU. Moet hij een visum?', 'Ja dat moet.', 'Alleen als hij langer dan een week blijft.', 'Nee dat hoeft niet.', 'C', 'Als EU-burger met een Nederlands paspoort hoef je geen visum voor reizen naar andere EU-landen zoals België.', null, null),
(228, 'Staatsinrichting en Rechtsstaat', 'Mogen vrouwen in Nederland hetzelfde werk doen als mannen?', 'Ja dat mogen ze.', 'Alleen als ze nog geen kinderen hebben.', 'Nee dat mogen ze niet.', 'A', 'In Nederland geldt gelijke behandeling van mannen en vrouwen op de arbeidsmarkt. Vrouwen mogen hetzelfde werk doen als mannen.', null, null),
(229, 'Staatsinrichting en Rechtsstaat', 'Wie mag nieuwe wetten aannemen in Nederland?', 'De gemeente.', 'De rechter.', 'Het parlement.', 'C', 'Nieuwe wetten worden aangenomen door het parlement (de Staten-Generaal), bestaande uit de Eerste en Tweede Kamer.', null, 1),
(230, 'Staatsinrichting en Rechtsstaat', 'Maura rijdt auto. Ze moet stoppen van de politie. Maura heeft rijbewijs. Rijden zonder rijbewijs is strafbaar. Wie bepaalt de straf?', 'De burgemeester.', 'De politie.', 'De rechter.', 'C', 'De straf voor strafbare feiten wordt bepaald door de rechter. De politie handhaaft de wet maar legt geen straffen op.', null, null),
(231, 'Geschiedenis en Geografie', 'Wat is een hoofdstad?', 'De grootste stad van een provincie of van een land.', 'De belangrijkste stad van een provincie of van een land.', 'De oudste stad van een provincie of van een land.', 'B', '', null, null),
(232, 'Geschiedenis en Geografie', 'Je wilt inchecken. Er staat: Te weinig saldo. Wat betekent dat?', 'Je moet ergens anders inchecken.', 'Er staat niet genoeg geld op je OV-chipkaart.', 'Je moet nog een keer inchecken.', 'B', '', null, null),
(233, 'Geschiedenis en Geografie', 'Welke provincie wordt door de Afsluitdijk beschermd?', 'Zeeland', 'Zuid-Holland', 'Flevoland', 'C', '', null, null),
(234, 'Geschiedenis en Geografie', 'Welke provincies worden vooral beschermd door de Deltawerken?', 'Noord-Holland, Friesland en Groningen', 'Flevoland, Utrecht en Gelderland', 'Zuid-Holland, Zeeland en Noord-Brabant', 'C', '', null, null),
(235, 'Geschiedenis en Geografie', 'Waarom zijn dijken en duinen belangrijk voor Nederland?', 'omdat Nederland lager dan de zee ligt', 'omdat er veel huizen op staan', 'omdat je er mooi kunt wandelen en fietsen', 'A', '', null, null),
(236, 'Geschiedenis en Geografie', 'Waarom hebben Nederlanders de Deltawerken gebouwd?', 'om nieuw land te maken', 'om de zee tegen te houden', 'om het strand groter te maken', 'B', '', null, null),
(237, 'Geschiedenis en Geografie', 'Waarom zijn Nederlanders blij met polders? Door de polders …', 'is er meer land om op te wonen en te werken.', 'zijn er veel molens.', 'overstroomt Nederland niet meer.', 'A', '', null, null),
(238, 'Geschiedenis en Geografie', 'Waarom lieten mensen in de 17e eeuw schilderijen maken?', 'De Nederlanders wilden hun huis gezellig maken.', 'De Nederlanders waren rijk en lieten dit graag zien.', 'De Nederlanders wilden graag verhalen laten zien.', 'B', '', null, null),
(239, 'Geschiedenis en Geografie', 'Waarom staan grachtenpanden aan het water?', 'omdat huizen daar goedkoop waren', 'omdat de Nederlanders veel producten over het water vervoerden', 'omdat er op andere plaatsen geen plek was om huizen te bouwen', 'B', '', null, null),
(240, 'Geschiedenis en Geografie', 'Hoe werd Nederland in de 17e eeuw rijk?', 'De Nederlanders konden goed varen en wonnen veel wedstrijden.', 'De Nederlanders voerden oorlog met andere landen.', 'De Nederlanders kochten en verkochten veel producten.', 'C', '', null, null),
(241, 'Geschiedenis en Geografie', 'Nederland is nu niet meer zo trots op de 17e eeuw. Waarom niet?', 'Andere landen waren rijker dan Nederland.', 'De Nederlanders gebruikten veel geweld.', 'De VOC handelde alleen met Azië.', 'B', '', null, null),
(242, 'Geschiedenis en Geografie', 'Amsterdam was een belangrijke stad in de 17e eeuw. Waarom?', 'Doordat er veel water is, konden de Nederlanders veel handelen.', 'Doordat er veel schilderijen waren, waren er veel musea.', 'Doordat er veel overstromingen waren, leerden de Nederlanders dijken bouwen.', 'A', '', null, null),
(243, 'Geschiedenis en Geografie', 'Ook Den Haag was een grote stad in de 17e eeuw. Waarom?', 'Hier lieten alle Nederlanders schilderijen maken.', 'Hier bewaarde de VOC de producten.', 'Hier praatte de Nederlandse regering over de handel.', 'C', '', null, null),
(244, 'Geschiedenis en Geografie', 'Waarom waren de koloniën belangrijk voor Nederland?', 'Nederland kreeg veel geld voor de producten uit de koloniën.', 'Nederland verkocht veel spullen aan de koloniën.', 'Nederland werd te klein voor het aantal mensen dat er woonde.', 'A', '', null, null),
(245, 'Geschiedenis en Geografie', 'Waarom waren tot slaaf gemaakte mensen belangrijk voor Nederland?', 'De tot slaaf gemaakte mensen kregen geen geld voor hun werk op de plantages. Daardoor werd Nederland rijker.', 'De tot slaaf gemaakte mensen kwamen in Nederland werken.', 'De tot slaaf gemaakte mensen kochten veel spullen van Nederland.', 'A', '', null, null),
(246, 'Geschiedenis en Geografie', 'In 1863 kwam er een einde aan de slavernij. Waarom waren de tot slaaf gemaakte mensen toch niet zo blij?', 'omdat ze het leven als tot slaaf gemaakte wel fijn vonden', 'omdat ze toen geen werk meer hadden', 'omdat ze nog tien jaar op de plantages moesten blijven werken', 'C', '', null, null),
(247, 'Geschiedenis en Geografie', 'Keti Koti is de feestdag om het einde van de slavernij te vieren. Waarom heeft deze feestdag een Surinaamse naam?', 'omdat er in Suriname als eerste een einde kwam aan de slavernij', 'omdat er alleen in Suriname slavernij was', 'omdat ze in Suriname begonnen zijn met deze feestdag', 'C', '', null, null),
(248, 'Geschiedenis en Geografie', 'Waarom is Keti Koti op 1 juli?', 'omdat in Suriname op 1 juli de zomervakantie begint', 'omdat slavernij sinds 1 juli 1863 niet meer mag', 'omdat Suriname op 1 juli onafhankelijk werd', 'B', '', null, null),
(249, 'Geschiedenis en Geografie', 'Wat doen mensen tijdens Keti Koti?', 'feestvieren', 'een herdenking houden', 'feestvieren en een herdenking houden', 'C', '', null, null),
(250, 'Geschiedenis en Geografie', 'Waarom bezette Duitsland Nederland tijdens de Tweede Wereldoorlog?', 'Hitler wilde in Nederland concentratiekampen bouwen.', 'Hitler wilde Nederland bevrijden.', 'Hitler wilde één groot land hebben.', 'C', '', null, null),
(251, 'Geschiedenis en Geografie', 'Waarom begon Hitler de Holocaust?', 'Joden werden niet geholpen door de geallieerden.', 'Joden mochten niet in het leger om tegen Duitsland te vechten.', 'Joden kregen de schuld van alle problemen in Europa.', 'C', '', null, null),
(252, 'Geschiedenis en Geografie', 'Waarom waren de geallieerden belangrijk voor Nederland?', 'De geallieerden waren tijdens de Tweede Wereldoorlog de baas in Nederland.', 'De geallieerden brachten tijdens de Holocaust Joden naar concentratiekampen.', 'De geallieerden hebben in 1945 Nederland bevrijd.', 'C', '', null, null),
(253, 'Geschiedenis en Geografie', 'Waarom zijn veel Nederlanders op 4 mei verdrietig?', 'Ze hebben geen vrije dag.', 'Ze denken aan de mensen die zijn doodgegaan in de oorlog.', 'Ze denken aan discriminatie.', 'B', '', null, null),
(254, 'Geschiedenis en Geografie', 'Waarom zijn veel Nederlanders op 5 mei blij?', 'Ze vieren dat de koning jarig is.', 'Ze vieren dat discriminatie strafbaar is.', 'Ze vieren dat ze vrij zijn.', 'C', '', null, null),
(255, 'Geschiedenis en Geografie', 'Er kwamen na de Tweede Wereldoorlog veel arbeidsmigranten naar Nederland. Waarom?', 'omdat er in Nederland veel werk was', 'omdat hun familie hier al werkte', 'omdat het niet veilig was in hun land van herkomst', 'A', '', null, null),
(256, 'Geschiedenis en Geografie', 'Er wonen in Nederland veel mensen met familie in Suriname. Waarom?', 'omdat het in Suriname niet veilig is', 'omdat Suriname vroeger een kolonie van Nederland was', 'omdat Suriname lid is van de EU', 'B', '', null, null),
(257, 'Geschiedenis en Geografie', 'Nederland is lid van de EU. Waarom is dat belangrijk voor Nederland?', 'omdat de Nederlandse regering de macht heeft in alle EU-landen', 'omdat het goed is voor de Nederlandse handel', 'omdat de Nederlanders in alle EU-landen met de euro kunnen betalen', 'B', '', null, null),
(258, 'Geschiedenis en Geografie', 'Nederland is lid van de VN en de NAVO. Waarom is dat belangrijk voor Nederland?', 'omdat Nederland niet genoeg eigen wetten en regels heeft', 'omdat Nederlanders dan over de hele wereld kunnen werken', 'omdat Nederland bescherming krijgt van de andere landen als dat nodig is', 'C', '', null, null),
(259, 'Wonen', 'Veel mensen die in Nederland een huis willen kopen zoeken een huis buiten de stad. Waarom doen ze dat?', 'Veel mensen willen een boerderij met dieren.', 'Er is meer werk buiten de stad dan in de stad.', 'Woningen zijn vaak buiten de stad goedkoper dan in de stad.', 'C', '', null, null),
(260, 'Wonen', 'Waarom is de huursector verdeeld in sociale huur en vrije huur?', 'Mensen met een hoog inkomen gaan dan sneller een huis kopen.', 'Mensen blijven dan niet te lang in een huis wonen.', 'Mensen met een laag inkomen kunnen dan ook een woning huren.', 'C', '', null, null),
(261, 'Wonen', 'In welke provincie zijn de huizen goedkoper?', 'Groningen', 'Noord-Holland', 'Amsterdam', 'A', '', null, null),
(262, 'Wonen', 'In welke provincie zijn de huizen goedkoper?', 'Zuid-Holland', 'Limburg', 'Den Haag', 'B', '', null, null),
(263, 'Wonen', 'In welke provincie zijn de huizen goedkoper?', 'Utrecht', 'Drenthe', 'Rotterdam', 'B', '', null, null),
(264, 'Wonen', 'Wat is waar?', 'Je hebt alleen een hypotheek nodig als je een heel duur huis wilt kopen.', 'Je mag zelf kiezen hoeveel geld je voor een huis leent van de bank.', 'Als je een hypotheek wilt wil de bank weten of je werk hebt.', 'C', '', null, null),
(265, 'Wonen', 'Wat is waar?', 'De verkoper van een huis moet zeggen wat hij van een bod vindt.', 'De koper kan de prijs van een koophuis niet veranderen.', 'De notaris zegt hoeveel je moet betalen voor een huis.', 'A', '', null, null),
(266, 'Wonen', 'Veel mensen vragen een makelaar om hulp bij het kopen van een woning. Waarom?', 'Het is makkelijker om een koopwoning te vinden als je een makelaar om hulp vraagt.', 'Je moet altijd een makelaar om hulp vragen als je een woning wilt kopen.', 'Het is goedkoper om een koopwoning te vinden als je een makelaar om hulp vraagt.', 'A', '', null, null),
(267, 'Wonen', 'Wat hoort bij de mensen? Luc en Marie zijn al vier jaar samen en willen voor altijd bij elkaar blijven. Ze willen zich bij de gemeente inschrijven als man en vrouw. Ze willen dat doen met een groot feest met familie en vrienden.', 'het geregistreerd partnerschap', 'het huwelijk', 'samenwonen', 'B', '', null, null),
(268, 'Wonen', 'Wat hoort bij de mensen? Toby en Diego zijn verliefd. Ze willen het liefst elke dag samen zijn maar ze willen zich nog niet bij de gemeente inschrijven als man en man. Daarvoor vinden zij zichzelf nog te jong. Eerst maar eens samen een huis zoeken.', 'het huwelijk', 'het geregistreerd partnerschap', 'samenwonen', 'C', '', null, null),
(269, 'Wonen', 'Wat hoort bij de mensen? Sama en Zeynep hebben een relatie en willen samen een kindje. Ze willen zich bij de gemeente inschrijven als vrouw en vrouw maar ze willen geen groot feest. Ze willen vooral dat alles goed geregeld is voor hun kind.', 'het huwelijk', 'het geregistreerd partnerschap', 'samenwonen', 'B', '', null, null),
(270, 'Wonen', 'Feng huurt een woning. In het huurcontract staat dat de huurprijs één keer per jaar een beetje omhoog mag. De verhuurder heeft in zes maanden al twee keer de huurprijs hoger gemaakt. Mag dat?', 'Ja de verhuurder mag zelf beslissen hoe duur de woning is.', 'Ja als de huurder de nieuwe prijs ook goed vindt.', 'Nee dat is contractbreuk.', 'C', '', null, null),
(271, 'Wonen', 'Feng heeft een klacht over de hogere huur. Wat kan hij het beste doen?', 'de oude huurprijs blijven betalen', 'de verhuurder een e-mail sturen', 'stoppen met huur betalen', 'A', '', null, null),
(272, 'Wonen', 'Feng vertelt zijn klacht over de huurverhoging aan de verhuurder. De verhuurder luistert niet. Wat kan Feng nu het beste doen?', 'zeggen dat hij zijn huurcontract wil stopzetten', 'naar de Huurcommissie gaan', 'stoppen met huur betalen', 'B', '', null, null),
(273, 'Wonen', 'Feng heeft een klacht over zijn huurwoning. Kan hij stoppen met huur betalen tot het probleem opgelost is?', 'Nee dat is contractbreuk.', 'Ja dan zal de verhuurder wel luisteren.', 'Ja als hij alles later wel betaalt.', 'A', '', null, null),
(274, 'Wonen', 'Nuria wil graag een woning huren. Ze heeft weinig geld. De verhuurder kiest daarom toch iemand anders. Mag dat?', 'Ja de verhuurder mag regels over het inkomen hebben.', 'Nee dat is discriminatie.', 'Hierover staat niets in de wet.', 'A', '', null, null),
(275, 'Wonen', 'Aihan huurt een woning maar ze heeft overlast: de radio van de buren staat altijd erg hard. Wat kan ze het beste als eerste doen?', 'naar de Huurcommissie gaan', 'met de buren praten', '112 bellen', 'B', '', null, null),
(276, 'Wonen', 'Aihan heeft met de buren gepraat maar ze willen de radio niet zacht zetten. Aihan heeft nog steeds overlast. Wat kan ze nu het beste doen?', 'naar de Huurcommissie gaan', 'een e-mail naar de verhuurder sturen', '112 bellen', 'B', '', null, null),
(277, 'Wonen', 'Waar moet je toeslagen aanvragen?', 'bij de woningcorporatie', 'bij Dienst Toeslagen', 'bij de gemeente', 'B', '', null, null),
(278, 'Wonen', 'Meneer Sanchez woont in een huurhuis en krijgt huurtoeslag. Zijn inkomen gaat omhoog. Wat moet hij nu doen?', 'Hij moet extra huurtoeslag aanvragen bij Dienst Toeslagen.', 'Niets zijn huurtoeslag verandert vanzelf mee.', 'Hij moet zijn nieuwe inkomen doorgeven aan Dienst Toeslagen.', 'C', '', null, null),
(279, 'Wonen', 'Mahmoud geeft aan Dienst Toeslagen door dat hij een nieuwe baan heeft. Wat doet Dienst Toeslagen?', 'Dienst Toeslagen doet niets want de huur van Mahmouds huis blijft hetzelfde.', 'Dienst Toeslagen kijkt of hij nog steeds recht heeft op huurtoeslag en op hoeveel.', 'Dienst Toeslagen stopt zijn huurtoeslag onmiddelijk.', 'B', '', null, null),
(280, 'Wonen', 'Bartek heeft huurtoeslag. Hij gaat samenwonen met Lauren. Moet hij dit doorgeven aan Dienst Toeslagen?', 'Ja want Dienst Toeslagen kijkt naar het inkomen van Bartek en Lauren samen.', 'Nee want de huur blijft hetzelfde.', 'Alleen als Bart en Lauren zijn getrouwd.', 'A', '', null, null),
(281, 'Wonen', 'Bartek heeft huurtoeslag. Hij gaat samenwonen met Lauren. Verandert de huurtoeslag?', 'Nee want Bartek heeft nog hetzelfde inkomen. De huurtoeslag blijft hetzelfde.', 'Ja want Bartek en Lauren hebben nu samen meer inkomen. Daardoor wordt de huurtoeslag hoger.', 'Ja want Bartek en Lauren hebben nu samen meer inkomen. Daardoor wordt de huurtoeslag lager.', 'C', '', null, null),
(282, 'Wonen', 'Je moet een nieuwe energieleverancier kiezen. Hoe kies je die?', 'Je kan niet kiezen, je hebt één energieleverancier met de hele gemeente.', 'Je kiest zelf een energieleverancier online.', 'Je hoeft niets te doen. Dit gaat automatisch.', 'B', '', null, null),
(283, 'Wonen', 'Samuel kiest een energiecontract met een vast tarief. Wat kan hiervoor een reden zijn?', 'Het contract heeft geen einde dus Samuel hoeft dan nooit meer een nieuw contract te nemen.', 'Het tarief blijft dan hetzelfde tot het contract stopt dus Samuel weet altijd welke prijs hij voor zijn energie betaalt.', 'Samuel betaalt dan elke maand het laagste tarief dus dit is goedkoper.', 'B', '', null, null),
(284, 'Wonen', 'Nuria gaat verhuizen en heeft water nodig. Wat is waar?', 'Nuria hoeft niets te doen want als je verhuist heb je meteen een waterbedrijf.', 'Nuria moet zich zelf aanmelden bij een waterbedrijf.', 'Nuria kan kiezen uit verschillende waterbedrijven.', 'B', '', null, null),
(285, 'Wonen', 'Zeynep wil graag televisiekijken. Wat is waar?', 'De prijzen voor internet telefoon en televisie zijn bij elke provider hetzelfde dus Zeynep betaalt bij elke provider hetzelfde bedrag.', 'Er is één provider voor internet telefoon en televisie per deel van Nederland dus Zeynep kan niet kiezen.', 'Zeynep moet voor internet telefoon en televisie een abonnement bij een provider kiezen.', 'C', '', null, null),
(286, 'Wonen', 'Yana woont in Den Haag. Ze gooit afval weg. Wat is waar?', 'De regels voor afvalinzameling en afval scheiden zijn voor haar hetzelfde als voor haar vriendin die in Rotterdam woont.', 'De regels voor afvalinzameling en afval scheiden zijn voor haar hetzelfde als voor haar buurvrouw.', 'De regels voor afvalinzameling en afval scheiden zijn voor haar hetzelfde als voor haar ouders die in Leiden wonen.', 'B', '', null, null),
(287, 'Wonen', 'Je betaalt elk jaar gemeentelijke belastingen. Welke belastingen betaal je niet aan de gemeente?', 'motorrijtuigenbelasting', 'rioolbelasting', 'hondenbelasting', 'A', '', null, null),
(288, 'Wonen', 'Veel mensen vinden afval scheiden belangrijk. Waarom?', 'Dan zijn de containers minder zwaar.', 'Dan wordt het afval niet vies.', 'Dan kan het afval nog een keer gebruikt worden.', 'C', '', null, null),
(289, 'Gezondheid en Gezondheidszorg', 'Lars verhuist naar een andere gemeente. Hoe krijgt hij een nieuwe huisarts?', 'Hij krijgt een huisarts van de gemeente.', 'Hij zoekt zelf een huisartsenpraktijk en schrijft zich daar in.', 'Hij krijgt een huisarts van de verzekeraar.', 'B', '', null, null),
(290, 'Gezondheid en Gezondheidszorg', 'Lars heeft zich ingeschreven bij een nieuwe huisarts. De nieuwe huisarts wil informatie over Lars. Mag de vorige huisarts deze informatie delen?', 'Misschien als Lars toestemming geeft.', 'Ja artsen mogen elkaar alles vertellen. Anders kunnen ze de patiënt niet goed helpen.', 'Nee door het medisch beroepsgeheim mag een arts nooit informatie delen.', 'A', '', null, null),
(291, 'Gezondheid en Gezondheidszorg', 'Zeynep vindt haar huisarts niet goed. Kan ze naar een andere huisartsenpraktijk gaan?', 'Nee ze moet bij haar huisarts blijven behalve als ze verhuist.', 'Misschien als de verzekeraar toestemming geeft.', 'Ja ze kan zich inschrijven bij een andere huisartsenpraktijk in haar gemeente.', 'C', '', null, null),
(292, 'Gezondheid en Gezondheidszorg', 'Kumar is depressief en kan niet meer werken. Wie moet hij bellen?', 'de huisartsenpost', 'de gemeente', 'de huisartsenpraktijk', 'A', '', null, null),
(293, 'Gezondheid en Gezondheidszorg', 'Mert moet naar de huisarts maar spreekt geen Nederlands. Wat kan hij doen?', 'Mert kan zijn zoon van 10 jaar meenemen naar de huisarts.', 'Mert kan een huisarts in Nederland zoeken die zijn taal spreekt.', 'Mert kan bij zijn huisartsenpraktijk om een tolk vragen.', 'C', '', null, null),
(294, 'Gezondheid en Gezondheidszorg', 'Een arts heeft een medisch beroepsgeheim. Wat betekent dat?', 'Een arts moet toestemming van de patiënt hebben om zijn informatie te mogen delen.', 'Een arts mag informatie over zijn patiënten delen met collega''s maar niet met familie en vrienden.', 'Een arts mag nooit persoonlijke informatie delen want dat doet de patiënt zelf.', 'A', '', null, null),
(295, 'Gezondheid en Gezondheidszorg', 'De dochter van Sama is gevallen en heeft pijn aan haar kin. Mag Sama haar dochter naar het ziekenhuis brengen?', 'Nee ze moet eerst de huisarts of de huisartsenpost bellen.', 'Ja ze kan altijd kijken of artsen in het ziekenhuis tijd hebben om te helpen.', 'Nee ze moet eerst 112 bellen.', 'B', '', null, null),
(296, 'Gezondheid en Gezondheidszorg', 'Feng heeft buikpijn. Hij gaat naar de huisarts. Heeft hij een verwijsbrief nodig?', 'ja', 'nee', 'Het hoeft niet maar het kan wel.', 'C', '', null, null),
(297, 'Gezondheid en Gezondheidszorg', 'Samuel kan niet goed zien. Hij wil naar een oogspecialist. Heeft hij een verwijsbrief nodig?', 'ja', 'nee', 'Het hoeft niet maar het kan wel.', 'C', '', null, null),
(298, 'Gezondheid en Gezondheidszorg', 'Marie slaapt slecht. Ze wil naar een psycholoog. Heeft ze een verwijsbrief nodig?', 'ja', 'nee', 'Het hoeft niet maar het kan wel.', 'A', '', null, null),
(299, 'Gezondheid en Gezondheidszorg', 'Zeynep wil sterkere spieren. Ze wil naar een fysiotherapeut. Heeft ze een verwijsbrief nodig?', 'ja', 'nee', 'Het hoeft niet maar het kan wel.', 'C', '', null, null),
(300, 'Gezondheid en Gezondheidszorg', 'Sama kan niet goed traplopen. Ze wil graag een traplift van de gemeente. Heeft ze een verwijsbrief nodig?', 'ja', 'nee', 'Het hoeft niet maar het kan wel.', 'B', '', null, null),
(301, 'Gezondheid en Gezondheidszorg', 'Je wilt medicijnen halen. Wat is waar?', 'Voor veel medicijnen heb je een recept van de huisarts nodig.', 'Je kunt alle medicijnen bij de drogist kopen.', 'Voor medicijnen bij de drogist heb je een recept nodig.', 'A', '', null, null),
(302, 'Gezondheid en Gezondheidszorg', 'Diego is ziek. Hij heeft keelpijn en hoest veel. Wat kan hij het beste doen?', 'naar de huisarts gaan', 'de huisarts bellen en een recept voor hoestdrank vragen', 'bij de drogist of apotheek hoestdrank kopen', 'A', '', null, null),
(303, 'Gezondheid en Gezondheidszorg', 'Mahmoud heeft rugpijn. Hij gaat naar de huisarts en vraagt om medicijnen. De huisarts wil geen medicijnen voorschrijven. Hij zegt: ''Mahmoud je moet meer bewegen.'' Wat kan Mahmoud het beste doen?', 'bij de apotheek medicijnen halen', 'elke dag wandelen', 'naar een andere dokter gaan', 'B', '', null, null),
(304, 'Gezondheid en Gezondheidszorg', 'De meeste mensen in Nederland gaan één of twee keer per jaar naar de tandarts. Waarom?', 'omdat de tandarts helpt om je gebit gezond te houden', 'omdat het moet van de verzekeringsmaatschappij', 'omdat het verplicht is in Nederland', 'A', '', null, null),
(305, 'Gezondheid en Gezondheidszorg', 'Sommige mensen in Nederland gaan ook één of twee keer per jaar naar de mondhygiënist. Waarom?', 'omdat je dan minder vaak naar de tandarts hoeft', 'omdat het gratis is in Nederland', 'omdat de mondhygiënist helpt om je gebit schoon te houden', 'C', '', null, null),
(306, 'Gezondheid en Gezondheidszorg', 'In Nederland is de zorgverzekering verplicht. Waarom moet iedereen in Nederland een zorgverzekering hebben?', 'omdat iedereen veel zorg nodig heeft', 'omdat de regering niet genoeg geld heeft voor de zorg', 'omdat de zorg veel geld kost', 'C', '', null, null),
(307, 'Gezondheid en Gezondheidszorg', 'Mahmoud heeft een recept voor medicijnen. De medicijnen worden vergoed door de zorgverzekeraar. Mahmoud gaat naar de apotheek maar hij moet betalen voor de medicijnen. Hoe kan Mahmoud de kosten declareren?', 'De zorgverzekeraar stuurt hem een rekening.', 'Hij belt de zorgverzekeraar.', 'Hij vult op de website van de zorgverzekeraar een formulier in.', 'C', '', null, null),
(308, 'Gezondheid en Gezondheidszorg', 'Het is november. Samuel heeft pijn aan zijn knie. Hij wil naar de fysiotherapeut. Hij heeft geen aanvullende verzekering. Wat kan hij doen?', 'Hij kan een aanvullende verzekering afsluiten en meteen een afspraak maken. Dan betaalt de zorgverzekeraar de fysiotherapie.', 'Hij kan een verwijsbrief aan de huisarts vragen. Dan is de fysiotherapeut gratis.', 'Hij kan voor volgend jaar een aanvullende verzekering afsluiten en een afspraak maken in januari. Dan betaalt de zorgverzekeraar de fysiotherapie.', 'B', '', null, null),
(309, 'Gezondheid en Gezondheidszorg', 'Luc moet het hele bedrag van het eigen risico betalen maar hij heeft niet genoeg geld. Wat kan hij doen?', 'Hij kan wisselen naar een andere zorgverzekeraar.', 'Hij kan zijn zorgverzekeraar bellen om door te geven dat hij gespreid wil betalen.', 'Hij kan een vriend of familielid vragen om hem geld te lenen.', 'B', '', null, null),
(310, 'Gezondheid en Gezondheidszorg', 'De baby van Marieke en Toby is geboren. Wat moeten Marieke en Toby doen?', 'aangifte doen van de geboorte bij de gemeente', 'naar het consultatiebureau met de baby', 'het kind bijschrijven op de zorgverzekering van Marieke of van Toby', 'A', '', null, null),
(311, 'Gezondheid en Gezondheidszorg', 'Wat staat er in de Nederlandse wet over orgaandonatie?', 'De arts kiest of je donor bent.', 'Iedereen in Nederland is donor.', 'Je mag kiezen of je donor wilt zijn maar je moet dit wel doorgeven.', 'C', '', null, null),
(312, 'Gezondheid en Gezondheidszorg', 'Hoe kun je doorgeven of je wel of geen donor wilt zijn?', 'Je moet dit in het Donorregister invullen.', 'Je moet dit aan je huisarts vertellen.', 'Je moet hiervoor het ziekenhuis bellen.', 'A', '', null, null),
(313, 'Gezondheid en Gezondheidszorg', 'Wat is waar over orgaandonatie?', 'Na de orgaandonatie kun je zien dat de organen uit het lichaam zijn gehaald.', 'Als iemand na overlijden organen doneert dan mag de familie afscheid nemen.', 'In het Donorregister kun je invullen welke organen je wilt doneren.', 'B', '', null, null),
(314, 'Onderwijs en Opvoeding', 'Lees de tekst. Waar gaat Diego naartoe? Diego is 3 jaar. Hij spreekt thuis geen Nederlands. Als hij 4 jaar is wil hij graag naar de basisschool.', 'het speciaal onderwijs', 'de buitenschoolse opvang', 'de voorschoolse educatie', 'C', '', null, null),
(315, 'Onderwijs en Opvoeding', 'Lees de tekst. Waar gaat Lauren naartoe? Lauren is 5 jaar. Ze kan niet goed zien. Toch gaat ze naar school.', 'het speciaal onderwijs', 'het voortgezet onderwijs', 'de openbare basisschool', 'A', '', null, null),
(316, 'Onderwijs en Opvoeding', 'Lees de tekst. Waar gaat Luc naartoe? Luc is 9 jaar. Hij is om 15.00 uur vrij van school maar zijn ouders zijn nog op hun werk.', 'de middelbare school', 'het voortgezet onderwijs', 'de buitenschoolse opvang', 'C', '', null, null),
(317, 'Onderwijs en Opvoeding', 'Lees de tekst. Waar gaat Sama naartoe? Sama is 10 jaar. Op haar school zitten veel verschillende kinderen: veel kinderen hebben geen religie sommige gaan naar de kerk of de moskee.', 'het kinderdagverblijf', 'het voortgezet onderwijs', 'de openbare basisschool', 'C', '', null, null),
(318, 'Onderwijs en Opvoeding', 'Lees de tekst. Waar gaat Toby naartoe? Toby is 13 jaar. Hij heeft veel verschillende docenten dat vindt hij leuk.', 'het voortgezet onderwijs', 'het kinderdagverblijf', 'de basisschool', 'A', '', null, null),
(319, 'Onderwijs en Opvoeding', 'Juffen en meesters willen graag met de ouders praten over de ontwikkeling van het kind. Hoe kan de juf of meester dit doen?', 'De juf of meester gaat op bezoek bij de ouders.', 'De juf of meester belt de ouders.', 'De juf of meester heeft een oudergesprek met de ouders.', 'C', '', null, null),
(320, 'Onderwijs en Opvoeding', 'Juffen en meesters zijn vaak direct. Waarom kan dit fijn zijn?', 'De ouders leren dan zelf om ook direct te zijn.', 'De juf of meester doet de ouders dan geen pijn.', 'De ouders weten dan wat de juf of meester echt denkt of voelt.', 'C', '', null, null),
(321, 'Onderwijs en Opvoeding', 'Juffen en meesters vinden het vaak fijn als ouders komen helpen bij activiteiten op school. Waarom is dit ook voor de ouders fijn?', 'De ouders weten dan wat hun kind op school doet.', 'De ouders leren de juf of meester kennen.', 'De ouders leren de andere ouders kennen.', 'A', '', null, null),
(322, 'Onderwijs en Opvoeding', 'Juffen en meesters vieren graag de verjaardagen van de kinderen op school. Hoe doen ze dit?', 'Het jarige kind trakteert.', 'De juf of meester geeft het jarige kind iets lekkers.', 'De klas zingt voor het jarige kind.', 'C', '', null, null),
(323, 'Onderwijs en Opvoeding', 'Wat is waar over vervolgopleidingen?', 'Als je een vervolgopleiding gaat doen dan moet je eerst de toelatingseisen controleren.', 'Als je na het vwo naar de universiteit wilt dan heb je toestemming van de docent nodig.', 'Als je vmbo doet dan kun je daarna meteen naar het hbo.', 'A', '', null, null),
(324, 'Onderwijs en Opvoeding', 'Soms mag je een opleiding niet doen. Wat is een reden om een opleiding niet te mogen doen?', 'Je hebt een vak nodig voor de opleiding maar je hebt dat vak op de middelbare school niet gevolgd.', 'Je bent jonger dan 18 jaar.', 'Het niveau dat je op de middelbare school hebt gehaald is niet het goede niveau voor de opleiding.', 'A', '', null, null),
(325, 'Onderwijs en Opvoeding', 'Alle kinderen in Nederland hebben kwalificatieplicht. Waarom is er in Nederland kwalificatieplicht?', 'Het zorgt ervoor dat ouders niet thuis hoeven te zijn voor hun kinderen.', 'Het zorgt ervoor dat jonge mensen kans hebben op een betere baan.', 'Het zorgt ervoor dat jonge mensen naar school blijven gaan.', 'B', '', null, null),
(326, 'Onderwijs en Opvoeding', 'De dochter van Toby en Lauren is 12 jaar. Ze gooit haar drinken over de laptop van de buurvrouw. Wie is er juridisch aansprakelijk?', 'Toby en Lauren', 'de dochter van Toby en Lauren', 'Lauren', 'A', '', null, null),
(327, 'Onderwijs en Opvoeding', 'De dochter van Yana is 20 jaar. Ze rijdt in de auto van Yana. Ze rijdt tegen een andere auto. Wie is er juridisch aansprakelijk?', 'de bestuurder van de andere auto', 'Yana', 'de dochter van Yana', 'C', '', null, null),
(328, 'Onderwijs en Opvoeding', 'De dochter van Bartek is vaak moe. Wie kan hierbij helpen?', 'de huisarts', 'de school', 'de Raad voor de Kinderbescherming', 'A', '', null, null),
(329, 'Onderwijs en Opvoeding', 'De zoon van Zeynep vindt leren moeilijk. Wie kan hierbij helpen?', 'de school', 'het ziekenhuis', 'de gemeente', 'A', '', null, null),
(330, 'Onderwijs en Opvoeding', 'Mariam heeft vragen over de opvoeding van haar dochter. Wie kan hierbij helpen?', 'Dienst Toeslagen', 'de huisartsenpost', 'het Centrum voor Jeugd en Gezin', 'C', '', null, null),
(331, 'Onderwijs en Opvoeding', 'Veel kinderen zijn ziek door een nieuwe kinderziekte. Wie kan hierbij helpen?', 'de Raad voor de Kinderbescherming', 'jeugdzorg', 'de GGD', 'C', '', null, null),
(332, 'Onderwijs en Opvoeding', 'Een kind is thuis niet veilig. Wie kan hierbij helpen?', 'de Raad voor de Kinderbescherming', 'de mantelzorger', 'de psycholoog', 'A', '', null, null),
(333, 'Onderwijs en Opvoeding', 'Marie heeft net haar eerste kind gekregen. Ze wil kinderbijslag aanvragen. Waar moet ze dit doen?', 'bij de Sociale Verzekeringsbank (SVB)', 'bij DUO', 'bij Dienst Toeslagen', 'A', '', null, null),
(334, 'Onderwijs en Opvoeding', 'Wie betalen de kosten van de kinderopvang?', 'Dienst Toeslagen en de kinderopvang', 'de ouders en de kinderopvang', 'de ouders en Dienst Toeslagen', 'C', '', null, null),
(335, 'Onderwijs en Opvoeding', 'Aihan werkt drie dagen per week. Haar dochter gaat dan naar de kinderopvang. Aihan wil kinderopvangtoeslag aanvragen. Waar moet ze dit doen?', 'bij Dienst Toeslagen', 'bij de kinderopvang', 'bij de gemeente', 'A', '', null, null),
(336, 'Onderwijs en Opvoeding', 'Toby heeft niet veel geld. Hij kan de ouderbijdrage niet betalen. Wat moet hij doen?', 'Hij moet de gemeente bellen.', 'Hij moet studiefinanciering aanvragen.', 'Hij moet dit vertellen aan de school.', 'C', '', null, null),
(337, 'Onderwijs en Opvoeding', 'Lars gaat bij het ROC een opleiding voor timmerman doen. Hij wil studiefinanciering aanvragen. Waar moet hij dit doen?', 'bij de gemeente', 'bij zijn school', 'bij DUO', 'C', '', null, null),
(338, 'Onderwijs en Opvoeding', 'Mert gaat studeren aan de universiteit. Hoe kan hij zijn studie betalen?', 'Zijn ouders kunnen een deel van zijn studie betalen.', 'Hij kan gaan werken.', 'Hij kan studiefinanciering krijgen.', 'B', '', null, null),
(339, 'Werk en Inkomen', 'Yana is pas één jaar in Nederland. Ze wil meer leren over werken in Nederland. Waar kan Yana naartoe?', 'DUO', 'IDW', 'de MAP', 'B', '', null, null),
(340, 'Werk en Inkomen', 'Mahmoud vindt werk vinden moeilijk. Hij zoekt hulp. Waar kan Mahmoud naartoe?', 'de gemeente', 'het uitzendbureau', 'de vacaturebank', 'B', '', null, null),
(341, 'Werk en Inkomen', 'Marieke wil graag iets doen. Ze hoeft geen geld voor het werk. Waar kan Marieke naartoe?', 'het vrijwilligerswerk', 'de vereniging', 'het bedrijf', 'A', '', null, null),
(342, 'Werk en Inkomen', 'Zeynep wil graag werken. Hoe kan ze werk zoeken?', 'via een uitzendbureau', 'in een vacaturebank', 'via haar netwerk', 'A', '', null, null),
(343, 'Werk en Inkomen', 'Bartek kan geen werk vinden. Hoe kan Bartek zijn kans op werk groter maken?', 'een opleiding doen', 'Nederlands leren', 'vrijwilligerswerk doen', 'A', '', null, null),
(344, 'Werk en Inkomen', 'Diego Lars en Zeynep solliciteren naar een baan in de keuken van een restaurant. Wie heeft de beste motivatie?', 'Lars zegt: ''Voor dit werk krijg je een goed salaris.''', 'Zeynep zegt: ''Ik vind het fijn om eten te maken.''', 'Diego zegt: ''Dit is makkelijk werk.''', 'B', '', null, null),
(345, 'Werk en Inkomen', 'Feng leest een vacature. Hij begrijpt niet alles. Hoe kan Feng meer informatie krijgen?', 'een sollicitatiebrief schrijven', 'de arbeidsvoorwaarden lezen', 'het bedrijf bellen', 'C', '', null, null),
(346, 'Werk en Inkomen', 'Marie heeft een sollicitatiegesprek. Hoe kan ze zich goed voorbereiden op het sollicitatiegesprek?', 'lezen over het bedrijf en vragen bedenken', 'bedenken waarom ze niet bij andere bedrijven wil werken', 'aan haar familie en vrienden vertellen dat ze gaat solliciteren', 'A', '', null, null),
(347, 'Werk en Inkomen', 'Wat is waar?', 'In Nederland werkt iedereen hetzelfde aantal uren per week.', 'In Nederland werken veel mensen in deeltijd.', 'In Nederland werken veel mensen meer dan 40 uur per week.', 'B', '', null, null),
(348, 'Werk en Inkomen', 'Wat is waar?', 'Alle medewerkers die hetzelfde werk doen hebben dezelfde arbeidsovereenkomst.', 'Alle medewerkers van een bedrijf hebben dezelfde arbeidsovereenkomst.', 'Iedere medewerker krijgt een persoonlijke arbeidsovereenkomst.', 'C', '', null, null),
(349, 'Werk en Inkomen', 'In een cao staan afspraken. Voor wie zijn die afspraken?', 'voor één werknemer en zijn werkgever', 'voor alle mensen in een bedrijf die hetzelfde werk doen', 'voor alle mensen in Nederland die hetzelfde werk doen', 'C', '', null, null),
(350, 'Werk en Inkomen', 'Mert Samuel en Marieke hebben een gesprek met hun werkgever. Wie onderhandelt over de arbeidsvoorwaarden?', 'Mert zegt: ''Ik wil graag bij jullie bedrijf komen werken.''', 'Marieke zegt: ''Ik vind 36 uur per week te veel. Ik wil graag 32 uur per week werken.''', 'Samuel zegt: ''Ik heb nog niet veel werkervaring maar ik leer snel.''', 'B', '', null, null),
(351, 'Werk en Inkomen', 'Yana heeft een beoordelingsgesprek met haar werkgever. Hoe kan ze zich op het gesprek voorbereiden?', 'door na te denken over hoe het op haar werk gaat en of ze vragen heeft', 'door na te denken over haar werkervaring en waarom ze bij het bedrijf wil werken', 'door na te denken over hoe haar werkgever functioneert', 'A', '', null, null),
(352, 'Werk en Inkomen', 'Waarom haalt een werkgever geld voor werknemersverzekeringen van het salaris af?', 'Door deze verzekeringen kun je meer vakantie krijgen.', 'Door deze verzekeringen krijg je geld als je niet meer kunt werken omdat je ziek bent.', 'Door deze verzekeringen krijg je geld als je geen werk meer hebt.', 'B', '', null, null),
(353, 'Werk en Inkomen', 'Waarom wordt er geld voor de Belastingdienst van je salaris afgehaald?', 'De overheid gebruikt de loonbelasting voor de afvalinzameling.', 'De overheid gebruikt de loonbelasting voor bijvoorbeeld goede wegen en scholen.', 'De overheid gebruikt de loonbelasting om werknemers te betalen.', 'B', '', null, null),
(354, 'Werk en Inkomen', 'Yana krijgt een digitale jaaropgave van haar werkgever. Ze zet de jaaropgave op de computer. Waarom doet ze dat?', 'Je moet de jaaropgave bewaren omdat de werkgever dat zegt.', 'Je werkgever mag nog vijf jaar geld terugvragen.', 'Je moet een jaaropgave minimaal vijf jaar bewaren voor de Belastingdienst.', 'C', '', null, null),
(355, 'Werk en Inkomen', 'Bij het bedrijf waar Luc werkt moeten veel mensen weg. Luc wil weten of dat mag. Hij zoekt hulp. Waar kan Luc naartoe?', 'de personeelsvereniging', 'de vakbond', 'de ondernemingsraad', 'B', '', null, null),
(356, 'Werk en Inkomen', 'Mahmoud is de baas van een bedrijf en moet een belangrijke beslissing nemen. Hij wil graag weten wat zijn werknemers van zijn idee vinden. Waar kan Mahmoud naartoe?', 'de vakbond', 'de ondernemingsraad', 'de personeelsvereniging', 'B', '', null, null),
(357, 'Werk en Inkomen', 'Marie werkt pas kort bij het bedrijf en wil graag mensen leren kennen. Ook wil ze graag kunnen meepraten over belangrijke beslissingen binnen het bedrijf. Waar kan Marie lid van worden?', 'de personeelsvereniging', 'de ondernemingsraad', 'de vakbond', 'B', '', null, null),
(358, 'Werk en Inkomen', 'Nuria vindt dat er niet genoeg voor het personeel wordt georganiseerd. Ze wil dit graag veranderen. Waar kan Nuria lid van worden?', 'de vakbond', 'de ondernemingsraad', 'de personeelsvereniging', 'A', '', null, null),
(359, 'Werk en Inkomen', 'Waarom zijn er vakbonden?', 'Een vakbond kan ervoor zorgen dat er meer mensen werken.', 'Een vakbond kan werknemers beschermen tegen een slechte werkgever.', 'Een vakbond kan ervoor zorgen dat werkgevers meer macht krijgen.', 'B', '', null, null),
(360, 'Werk en Inkomen', 'Helpt staken altijd?', 'Ja de werkgevers willen altijd heel graag dat werknemers weer gaan werken.', 'Nee staken zorgt er niet altijd voor dat de vakbond krijgt wat ze wil.', 'Ja staken zorgt er altijd voor dat de vakbond krijgt wat ze wil.', 'B', '', null, null),
(361, 'Werk en Inkomen', 'Wat is een goede reden om lid te worden van de OR?', 'Je leert veel over het bedrijf.', 'Je kunt veel leuke uitjes organiseren.', 'Je krijgt meer salaris.', 'A', '', null, null),
(362, 'Werk en Inkomen', 'Zeynep is buschauffeur. Zeynep wil meer pauze maar haar baas luistert niet naar haar. Zeynep is geen lid van de vakbond. Kan Zeynep de vakbond om advies vragen?', 'Nee dan moet ze eerst lid worden.', 'Nee dan moet haar baas eerst lid worden.', 'Ja dat kan.', 'C', '', null, null),
(363, 'Werk en Inkomen', 'Lauren wil een eigen boerderij beginnen. Ze gaat naar de Kamer van Koophandel. Waarom gaat ze naar de Kamer van Koophandel?', 'Bij de Kamer van Koophandel kan ze advies krijgen.', 'Bij de Kamer van Koophandel kan ze geld lenen.', 'Iedereen die een bedrijf begint moet zich inschrijven bij de Kamer van Koophandel.', 'A', '', null, null),
(364, 'Werk en Inkomen', 'Diego heeft een uitkering. Hij gaat als zzp''er een eigen bedrijf beginnen. Krijgt hij dan nog steeds een uitkering?', 'Nee als Diego zijn eigen bedrijf begint dan is hij een werknemer.', 'Nee als Diego zijn eigen bedrijf begint dan stopt zijn uitkering waarschijnlijk.', 'Ja als Diego zijn eigen bedrijf begint dan krijgt hij waarschijnlijk nog steeds een uitkering.', 'B', '', null, null),
(365, 'Werk en Inkomen', 'Feng wil een winkel starten. Wat moet hij in zijn ondernemingsplan zetten?', 'de spullen die hij gaat verkopen', 'de contracten met zijn medewerkers', 'de bonnen van zijn kassa', 'A', '', null, null),
(366, 'Werk en Inkomen', 'Mahmoud heeft een eigen bedrijf. Hij ligt in het ziekenhuis. Hij kan nu niet werken maar hij krijgt wel geld. Waarom krijgt hij toch geld?', 'Hij is door zijn werkgever verzekerd.', 'Hij heeft een arbeidsongeschiktheidsverzekering geregeld.', 'Hij krijgt een uitkering.', 'B', '', null, null),
(367, 'Werk en Inkomen', 'Mariam is assistente in het ziekenhuis en heeft veel rugpijn. Ze kan nu niet werken maar krijgt wel geld. Waarom krijgt ze toch geld?', 'Ze is door haar werkgever verzekerd.', 'Ze krijgt geld van de gemeente omdat ze in een ziekenhuis werkt.', 'Ze heeft een arbeidsongeschiktheidsverzekering.', 'A', '', null, null),
(368, 'Werk en Inkomen', 'Luc werkt al lang als werknemer bij een supermarkt. Hij wil stoppen met werken omdat hij oud is. Krijgt Luc een pensioen?', 'Ja hij krijgt via zijn werkgever pensioen.', 'Nee Luc kan geen pensioen krijgen.', 'Misschien als hij zelf pensioen heeft geregeld.', 'A', '', null, null),
(369, 'Werk en Inkomen', 'Sama is de baas van een bloemenwinkel. Ze is al oud en wil graag stoppen met werken. Hoe krijgt ze pensioen?', 'Ze krijgt van de gemeente pensioen.', 'Ze moet zelf pensioen regelen.', 'Ze krijgt via haar werkgever pensioen.', 'B', '', null, null),
(370, 'Instanties', 'Diego is nieuw in Nederland. Hij heeft nog nooit gewerkt. Hij heeft geld nodig. Waar kan Diego een uitkering aanvragen?', 'bij de gemeente', 'bij het UWV', 'bij Dienst Toeslagen', 'A', '', null, null),
(371, 'Instanties', 'Kumar krijgt bijstand. Welk recht heeft hij?', 'Hij mag een cursus doen.', 'Hij mag nee zeggen tegen werk dat de gemeente voor hem heeft gevonden.', 'Hij mag een WIA-uitkering aanvragen.', 'A', '', null, null),
(372, 'Instanties', 'Lars heeft een WW-uitkering. Welke plicht heeft hij?', 'Hij moet solliciteren.', 'Hij moet geld betalen.', 'Hij moet een opleiding doen.', 'A', '', null, null),
(373, 'Instanties', 'Mariam krijgt een uitkering van het UWV. Welke veranderingen moet zij aan het UWV doorgeven?', 'Mariam is zwanger.', 'Mariam gaat verhuizen.', 'De man van Mariam krijgt ander werk.', 'A', '', null, null),
(374, 'Instanties', 'Feng is geslaagd voor zijn rijexamen. Waar kan hij zijn rijbewijs aanvragen?', 'bij de gemeente', 'bij het UWV', 'bij DUO', 'A', '', null, null),
(375, 'Instanties', 'Het paspoort van Marieke is te oud. Ze mag het niet meer gebruiken. Waar moet ze een nieuw paspoort aanvragen?', 'bij de gemeente', 'bij de Belastingdienst', 'bij de IND', 'A', '', null, null),
(376, 'Instanties', 'Sama komt uit Jemen. Ze wil een verblijfsvergunning aanvragen. Waar moet ze een verblijfsvergunning aanvragen?', 'bij de KVK', 'bij de gemeente', 'bij de IND', 'C', '', null, null),
(377, 'Instanties', 'Diego komt uit Brazilië maar hij woont al twaalf jaar in Nederland. Hij wil graag naturaliseren. Waar kan hij naturalisatie aanvragen?', 'bij de IND', 'bij de Belastingdienst', 'bij de gemeente', 'A', '', null, null),
(378, 'Instanties', 'Mahmoud is 38 jaar en komt uit Marokko. Hij heeft een verblijfsvergunning voor Nederland. Hij mag van de Marokkaanse wet geen afstand doen van zijn Marokkaanse nationaliteit. Mag Mahmoud een dubbele nationaliteit hebben?', 'Ja maar hij mag zijn Marokkaanse paspoort niet gebruiken in Nederland.', 'Ja want je mag twee nationaliteiten hebben als je volgens de wet van je land van herkomst geen afstand mag doen van je eerste nationaliteit.', 'Nee want je mag in Nederland maar één nationaliteit hebben.', 'B', '', null, null),
(379, 'Instanties', 'Mariam is 26 jaar en komt uit Eritrea. Ze is nu zes jaar in Nederland. Ze heeft een verblijfsvergunning. Ze spreekt al goed Nederlands. Ze mag van de Eritrese wet geen afstand doen van haar Eritrese nationaliteit. Mag Mariam naturaliseren?', 'Nee want je moet minimaal tien jaar in Nederland zijn om te mogen naturaliseren.', 'Ja want ze voldoet aan de voorwaarden voor naturalisatie.', 'Nee want je mag alleen naturaliseren als je afstand doet van de nationaliteit van je land van herkomst.', 'B', '', null, null),
(380, 'Instanties', 'Samuel en zijn zoon lopen op straat. De zoon van Samuel is 15 jaar. Moet de zoon van Samuel een identiteitsbewijs bij zich hebben?', 'Nee maar wel als hij naar het buitenland gaat.', 'Ja want hij is ouder dan 14 jaar.', 'Nee want hij is nog een kind.', 'B', '', null, null),
(381, 'Instanties', 'Yana zoekt een sociale huurwoning. De woningcorporatie wil graag weten of ze aan de voorwaarden voldoet. Daarom moet ze haar identiteitsbewijs en andere documenten opsturen. Moet Yana haar BSN doorgeven?', 'Nee want een woningcorporatie hoeft haar BSN niet te weten.', 'Ja want een woningcorporatie moet haar BSN weten.', '', 'B', '', null, null),
(382, 'Instanties', 'Bartek ziet een diefstal gebeuren. Wat kan Bartek doen?', '112 bellen en om de politie vragen', '112 bellen en om een ambulance vragen', '112 bellen en om de brandweer vragen', 'A', '', null, null),
(383, 'Instanties', 'De buren van Aihan zorgen voor overlast. Aihan heeft het al een aantal keer tegen de buren gezegd maar er verandert niets. Wat kan Aihan doen?', '112 bellen en om de politie vragen', '0900-8844 bellen', '112 bellen en om de brandweer vragen', 'B', '', null, null),
(384, 'Instanties', 'Mariam is opgelicht. Een man belde haar. Hij zei dat haar zoon geld nodig had. Ze heeft veel geld gegeven. Wat kan Mariam doen?', '0900-8844 bellen', '112 bellen en om de politie vragen', '112 bellen en om een ambulance vragen', 'B', '', null, null),
(385, 'Instanties', 'Toby ziet een ongeluk. Het slachtoffer heeft erg veel pijn. Wat kan Toby doen?', '112 bellen en om een ambulance vragen', '112 bellen en om de brandweer vragen', '112 bellen en om de politie vragen', 'A', '', null, null),
(386, 'Instanties', 'Bartek vindt dat de politie hem discrimineert. Waar kan hij bezwaar maken?', 'bij het Juridisch Loket', 'bij de politie', 'bij de gemeentelijke ombudsman', 'A', '', null, null),
(387, 'Instanties', 'Lars wacht al vijf maanden op huurtoeslag van Dienst Toeslagen. Dienst Toeslagen doet niets aan dit probleem. Wat kan Lars doen?', 'hulp vragen bij het Juridisch Loket', 'hulp vragen bij de woningcorporatie', 'hulp vragen bij de Nationale ombudsman', 'C', '', null, null),
(388, 'Instanties', 'Lauren krijgt hulp van een gemeentelijke ombudsman. Wat doet een gemeentelijke ombudsman?', 'Een gemeentelijke ombudsman helpt bij problemen met de gemeente.', 'Een gemeentelijke ombudsman helpt bij problemen met DUO.', 'Een gemeentelijke ombudsman helpt bij problemen op je werk.', 'A', '', null, null),
(389, 'Instanties', 'Mahmoud en Marieke gaan scheiden. Ze hebben juridische hulp nodig. Wie kunnen ze om hulp vragen?', 'een advocaat', 'het Nibud', 'het wijkteam', 'A', '', null, null),
(390, 'Instanties', 'Yana heeft een advocaat nodig. Ze heeft een laag inkomen. Moet zij de advocaat betalen?', 'Ja ze moet de advocaat helemaal zelf betalen.', 'Nee het Juridisch Loket betaalt de advocaat voor haar.', 'Ja maar ze betaalt een bijdrage die past bij haar inkomen.', 'C', '', null, null),
(391, 'Staatsinrichting en Rechtsstaat', 'In deze straat mag je 30 kilometer per uur rijden. Wie controleert of mensen zich aan deze regel houden?', 'de politie', 'de rechter', 'de minister', 'A', '', null, null),
(392, 'Staatsinrichting en Rechtsstaat', 'Lars reist met de trein. Het treinpersoneel controleert zijn vervoersbewijs maar Lars heeft geen vervoersbewijs. Reizen zonder vervoersbewijs mag niet. Wie beslist welke straf Lars krijgt?', 'de politie', 'de rechter', 'het treinpersoneel', 'B', '', null, null),
(393, 'Staatsinrichting en Rechtsstaat', 'Marieke rijdt door een rood stoplicht. De politie geeft haar een boete. Wie beslist of door rood rijden strafbaar is?', 'de politie die geeft de boete', 'de minister die zet het in de wet', 'de rechter die leest het in de wet', 'B', '', null, null),
(394, 'Staatsinrichting en Rechtsstaat', 'Yana moest voor de rechter komen. Ze vindt de beslissing van de rechter niet goed. Wat kan ze doen?', 'de minister om hulp vragen', 'iemand van het Juridisch Loket meenemen naar de rechter', 'in hoger beroep gaan', 'C', '', null, null),
(395, 'Staatsinrichting en Rechtsstaat', 'Aihan is 40 jaar en komt uit China. Ze heeft niet de Nederlandse nationaliteit maar woont wel al zes jaar in Nederland en heeft een verblijfsvergunning. Er zijn gemeenteraadsverkiezingen in het dorp waar ze woont. Mag Aihan stemmen?', 'Ja want ze is ouder dan 18 jaar.', 'Ja want ze woont al langer dan vijf jaar in Nederland en heeft een verblijfsvergunning.', 'Nee want ze heeft niet de Nederlandse nationaliteit.', 'B', '', null, null),
(396, 'Staatsinrichting en Rechtsstaat', 'Bartek is 15 jaar. Er is een referendum in de stad waar hij woont. Mag Bartek stemmen?', 'Nee want hij is te jong.', 'Ja want hij woont in de stad waar het referendum is.', 'Ja want bij een referendum mag iedereen stemmen.', 'A', '', null, null),
(397, 'Staatsinrichting en Rechtsstaat', 'Feng is 18 jaar en heeft de Nederlandse nationaliteit. Hij wil stemmen bij de verkiezingen voor de provincies. Mag Feng stemmen?', 'Ja hij gebruikt zijn passief kiesrecht.', 'Ja hij gebruikt zijn actief kiesrecht.', 'Nee hij is niet oud genoeg om te stemmen.', 'B', '', null, null),
(398, 'Staatsinrichting en Rechtsstaat', 'Yana is 20 jaar en is lid van een politieke partij. De partij wil dat mensen op haar kunnen stemmen bij de verkiezingen. Mogen mensen op Yana stemmen?', 'Ja ze gebruikt haar passief kiesrecht.', 'Nee ze moet eerst een nieuwe politieke partij beginnen.', 'Ja ze gebruikt haar actief kiesrecht.', 'A', '', null, null),
(399, 'Staatsinrichting en Rechtsstaat', 'Zeynep is 27 jaar. Ze heeft niet de Nederlandse nationaliteit maar woont al acht jaar in Nederland. Er zijn verkiezingen voor de waterschappen. Mag Zeynep stemmen?', 'Nee want ze heeft niet de Nederlandse nationaliteit.', 'Ja want ze is ouder dan 18 jaar.', 'Ja want ze woont al langer dan vijf jaar in Nederland.', 'C', '', null, null),
(400, 'Staatsinrichting en Rechtsstaat', 'Er zijn verkiezingen voor het land. Mert heeft kiesrecht. Moet hij stemmen?', 'Ja stemmen is verplicht als je de Nederlandse nationaliteit hebt.', 'Ja stemmen is verplicht als je kiesrecht hebt.', 'Nee stemmen is een recht geen plicht.', 'C', '', null, null),
(401, 'Staatsinrichting en Rechtsstaat', 'Wanneer is het Koningsdag?', 'op 25 april', 'op 27 april', 'op 30 april', 'B', '', null, null),
(402, 'Staatsinrichting en Rechtsstaat', 'Wat viert Nederland op Koningsdag?', 'Nederland viert de verjaardag van de koning.', 'Nederland viert dat de koning getrouwd is.', 'Nederland viert dat Nederland een koning heeft.', 'A', '', null, null),
(403, 'Staatsinrichting en Rechtsstaat', 'Wat hoort bij Koningsdag?', 'de Troonrede', 'oranje kleding', 'een boom met lichtjes', 'B', '', null, null),
(404, 'Staatsinrichting en Rechtsstaat', 'Hoe heet het volkslied van Nederland?', 'Willem-Alexander', 'de koning van Hispanje', 'het Wilhelmus', 'C', '', null, null),
(405, 'Staatsinrichting en Rechtsstaat', 'Wanneer zingen de inwoners van Nederland het Wilhelmus?', 'bij belangrijke sportwedstrijden', 'op Koningsdag', 'bij de Nationale Dodenherdenking', 'A', '', null, null),
(406, 'Staatsinrichting en Rechtsstaat', 'Wat is waar?', 'Door de machtenscheiding heeft de overheid meer geld.', 'Door de machtenscheiding is de kans op corruptie bij de overheid kleiner.', 'Door de machtenscheiding heeft de politie meer macht.', 'B', '', null, null),
(407, 'Staatsinrichting en Rechtsstaat', 'Wat is waar?', 'In Nederland hoeft de overheid zich niet aan de wet te houden.', 'In Nederland zijn de wetten voor iedereen hetzelfde ook voor de overheid.', 'In Nederland mag de politie mensen verschillend behandelen.', 'B', '', null, null),
(408, 'Staatsinrichting en Rechtsstaat', 'Wat is waar?', 'In Nederland is er veel corruptie door de overheid.', 'In Nederland beslist de Nationale ombudsman of iemand betrokken is bij corruptie.', 'In Nederland is corruptie strafbaar.', 'C', '', null, null),
(409, 'Staatsinrichting en Rechtsstaat', 'Wat staat er in de Grondwet?', 'de religies van Nederland', 'de belangrijkste wetten van Nederland', 'de geschiedenis van Nederland', 'B', '', null, null),
(410, 'Staatsinrichting en Rechtsstaat', 'Wat zegt de Nederlandse wet over abortus?', 'Een abortus mag tot de 24ste week van de zwangerschap.', 'Een abortus door een specialist is strafbaar.', 'Een abortus mag tot de 30e week van de zwangerschap.', 'A', '', null, null),
(411, 'Staatsinrichting en Rechtsstaat', 'Wat zegt de Nederlandse wet over mannen en vrouwen?', 'Mannen zijn de baas over vrouwen.', 'Mannen en vrouwen zijn gelijk.', 'Vrouwen zijn de baas over mannen.', 'B', '', null, null),
(412, 'Staatsinrichting en Rechtsstaat', 'Welke rechten staan in de Grondwet?', 'Iedereen moet dezelfde religie hebben.', 'Iedereen mag studeren.', 'Iedereen is gelijk.', 'C', '', null, null),
(413, 'Staatsinrichting en Rechtsstaat', 'Wat mag niet in Nederland?', 'als vrouw naar de universiteit gaan', 'als man trouwen met een man', 'het dragen van een hoofddoek verbieden', 'C', '', null, null),
(414, 'Staatsinrichting en Rechtsstaat', 'Een man in Nederland schrijft in de krant: ''De politie is slecht!'' Mag de man dat schrijven?', 'Ja je mag je mening geven als je niet iets zegt dat strafbaar is.', 'Alleen als de politie het niet hoort.', 'Nee want dan geeft de politie je een straf.', 'A', '', null, null),
(415, 'Staatsinrichting en Rechtsstaat', 'Een moeder in Nederland gebruikt geweld tegen haar kind. Mag dat?', 'Ja de moeder is de baas van het kind.', 'Ja een kind moet doen wat zijn moeder zegt.', 'Nee dat is kindermishandeling.', 'C', '', null, null),
(416, 'Staatsinrichting en Rechtsstaat', 'Een nieuwe moskee in Nederland geeft een religieus feest. De gemeente is niet blij met het feest. Wanneer mag de gemeente het feest stoppen?', 'Dat mag altijd.', 'Alleen als de moskee zich niet aan de Nederlandse wet houdt.', 'Dat mag nooit.', 'B', '', null, null),
(417, 'Staatsinrichting en Rechtsstaat', 'Sama krijgt huurtoeslag. Ze wil weten welke gegevens Dienst Toeslagen van haar heeft. Wat kan Sama doen?', 'Ze kan inloggen op de website van Dienst Toeslagen en haar gegevens zien.', 'Niets want haar gegevens zijn geheim.', 'Dienst Toeslagen heeft geen gegevens van haar want ze heeft recht op privacy.', 'A', '', null, null),
(418, 'Staatsinrichting en Rechtsstaat', 'Marieke zoekt een baan. Ze heeft al veel gesolliciteerd maar ze wordt steeds niet gekozen. Ze denkt dat ze last heeft van discriminatie omdat ze zwanger is. Waar kan ze dit doorgeven?', 'bij het meldpunt Discriminatie', 'bij de huisarts', 'bij het UWV', 'A', '', null, null)
